/* 📖 „Co nowego” (NEWS) and the guide to every feature (HELP) – loaded only when needed: ⚙️ → 📖 Pomoc, the 🔍 search, the „Co nowego”
   slides after an update (import('./help.js')). NEWS_V in guide.js = NEWS[0].v. Plain data, no imports. */
/* what changed – shown once per phone after an update; the newest entry first */
export const NEWS=[
  {v:78,title:'Koperty na koncie 💰',scene:'calc',items:['💰 Stuknij konto w 👛 Konta: saldo podzielone na koperty – 🔻 spłaty i 🎯 cele zbierane na tym koncie – i 🪙 Wolne (tu wpadają drobne).','⇄ „Przesuń” między kopertami bez przelewu i ✨ „Rozdziel wolne” – sam rozkłada wolne pieniądze, najpierw najbliższy termin.','🎯 Cel może mieć swoje konto: przy celu „Edytuj” → „Zbieracie na koncie”.']},
  {v:77,title:'Za kogoś 🤝',scene:'happy',items:['🤝 Nowy przycisk w okienku wydatku: „Za kogoś”. Płacisz za coś dla kogoś (np. tacie), a on Wam odda – saldo konta i 🪙 drobne działają normalnie, ale zakup nie liczy się do budżetu.','✓ Gdy odda: 👛 Konta → 🔺 Nam winni → „✓ Oddał”. Zwrot nie jest przychodem. Oddał więcej? Nadwyżka jako 🎁 prezent (przychód) albo do oddania. Nie odda? „Wlicz do budżetu”.','🔔 Po 14 dniach bez zwrotu przypomni „Na dziś”.']},
  {v:76,title:'Szybciej ⚡',scene:'happy',items:['⚡ Aplikacja pobiera przy starcie i aktualizacji ok. 40 kB mniej: przewodnik i „Co nowego” ładują się dopiero, gdy ich potrzebujecie (Pomoc, 🔍 lupa, te slajdy).','⚡ Oszczędności rysują się szybciej przy długiej historii – kilka liczb jest zapamiętywanych zamiast liczenia od nowa przy każdym odświeżeniu.']},
  {v:75,title:'Drobne porządki 🧹',scene:'wink',items:['📥 Ponowne wczytanie kopii ze starej wersji aplikacji nie nadpisuje już poprawionych sald początkowych ani planów i mówi, ile wpisów naprawdę doszło.','↩️ „Cofnij” po usunięciu paska pensji nie policzy pensji dwa razy, gdy w tym miesiącu jest już nowy pasek.','📖 W Pomocy: Diagnostyka i trwała pamięć telefonu, przywracanie usuniętych celów, jak liczy się nadwyżka w zamknięciu miesiąca.']},
  {v:74,title:'Poprawki po przeglądzie 🔧',scene:'calc',items:['🛟 Poduszka bezpieczeństwa nie maleje przez cele, na które pieniądze leżą na rachunku inwestycyjnym (np. XTB) – liczy się tylko ta część celów, której tam nie ma. Szczegóły w „ⓘ” na karcie.','📈 Automat cen przy dużym spadku (krach) przyjmuje nową cenę już drugiego dnia, a wycena na koniec miesiąca czeka na potwierdzenie i bierze cenę z ostatniego dnia miesiąca. To samo pilnowanie dotyczy złota i funduszy PPK.','💼 Wypłata zawsze 30. dnia nie jest już brana za „koniec miesiąca” (zamknięcie, „Czy starczy?”).','📈 „Aktualizuj wartości” nie kasuje wartości konta wpisanej ręcznie; 👥 rozwinięta osoba w „Czy starczy?” zostaje otwarta; 🔔 zapisany wieczorem pasek nie wycisza „Wpiszcie dzisiejsze wydatki”; 📧 poduszka w mailu = ta w aplikacji.']},
  {v:73,title:'Wygodniej i bezpieczniej 📲',scene:'wink',items:['📲 Przycisk „Dodaj wydatek” na ekranie głównym albo blokady iPhone\'a: ⚙️ → 🤖 Automaty → 🗣️ Siri i skróty → „📲 Przycisk na ekranie” – instrukcja krok po kroku, ok. 2 minuty. Potem jedno stuknięcie otwiera nowy wydatek.','💾 Aplikacja prosi telefon, żeby nigdy nie czyścił jej danych – wpis zrobiony bez internetu, jeszcze niewysłany, nie przepadnie. Czy telefon się zgodził, widać w ⚙️ → 🛡️ Bezpieczeństwo → Diagnostyka („pamięć telefonu: trwała ✓”).']},
  {v:72,title:'Mniej na wierzchu 🧹',scene:'duo',items:['👥 „Czy starczy?” na dole Budżetu wygląda teraz jak karta kategorii: zwinięta, z „pigułką” ✅ starczy / 🟡 na styk / ⚠️ zabraknie, ile zostanie Mati, Wercia i wspólnym oraz jednym zdaniem. Stuknij, żeby zobaczyć szczegóły – zostaną otwarte, dopóki ich nie zwiniesz.','🔔 „Na dziś”: ciche rady (plan, „Czy starczy?”, Doradca, wycena nieruchomości) są zwinięte w „💡 Podpowiedzi” na samym dole i nie liczą się na dzwonku. Na górze zostaje to, co naprawdę na dziś.','👆 Małe przyciski (✓ przy opłatach, + / − przy kwocie, „Płaci”, „ⓘ”, rozwijane napisy) łatwiej trafić palcem – wyglądają tak samo, ale łapią stuknięcie trochę szerzej.']},
  {v:71,title:'Szybciej ⚡',scene:'happy',items:['⚡ Budżet i Analiza rysują się o ok. ¼–⅓ szybciej: Bailey i Ivo są rysowani raz i wracają na ekran gotowi (teraz na każdym ekranie, nie tylko na Budżecie), a duże kwoty w kafelkach dopasowują się za jednym razem.','🔔 „Na dziś” i przypomnienia 🧭 Doradcy liczą się od nowa tylko wtedy, gdy coś się zmieniło.','🌡️ Termometr rynku pobiera się przy otwarciu aplikacji (i po kilku godzinach przerwy), a nie przy każdej zmianie u automatu – mniej danych w telefonie.','🎂 Doradca bierze wiek z ankiety („rok urodzenia”), gdy nie ma daty urodzin.']},
  {v:70,title:'Porządki i nowe testy 🧪',scene:'calc',items:['🛟 Poduszka bezpieczeństwa liczy się wszędzie tak samo – na karcie w Oszczędnościach, w 🧭 Doradcy i w mailu z podsumowaniem: konta oszczędnościowe w złotych (bez IKE, IKZE, PPK) plus konto „Poduszka”, minus pieniądze w celach.','📧 Mail z podsumowaniem liczy sklepy, plan na nowy miesiąc, opłaty stałe i wydatki roczne tak jak aplikacja (bez umów, które się skończyły, bez rocznych zapłaconych wcześniej).','📈 Analiza: przyszły miesiąc nie pokazuje już „✅ Zmieściło się”, Mati ↔ Wercia i 🎁 Money Wrapped pomijają projekty spoza budżetu i inne waluty, a eksport do Excela ma kolumnę z kwotą, która wpłynęła na konto w innej walucie.','🖨️ Podsumowanie trwającego roku: „Majątek – teraz” to stan na dziś, a średnia wydatków na miesiąc jest taka sama jak w Analizie → Rok.','🔻 Usunięcie zobowiązania można cofnąć („Cofnij”). Przeniesienie wpisu do innego miesiąca zapisuje się za jednym razem.','🧭 Doradca: brak odpowiedzi o reakcji na spadek liczy się ostrożnie (jak „Nie wiem”), emerytura po osiągniętym wieku nie każe odkładać fortuny co miesiąc, a w grudniu przy IKE do założenia jest dopisek „(do założenia)”.','🤖 Robot sprawdza teraz o wiele więcej: zapis, zmianę i usuwanie wpisów, wczytywanie starych kopii, daty wypłat, strażnika porządku i to, czy wersja demo zapisuje dane tak jak prawdziwy Firebase.']},
  {v:69,title:'Pilne poprawki po audycie 🛡️',scene:'lupa',items:['📧 Podsumowanie miesiąca i roku idzie tylko na Wasze dwa adresy – te, którymi logujecie się w aplikacji. Nikt obcy go nie dostanie, nawet gdyby założył konto.','🔁 „Przywróć” i „Cofnij” nie policzą opłaty stałej dwa razy, gdy w międzyczasie odhaczyliście ją jeszcze raz. Ponowne wczytanie listy wpisów nie przywraca już usuniętych ani poprawionych wpisów.','📅 Wydatek „co 2 lata” dodany albo zmieniony w „Edytuj” wpada do planu co drugi rok (pierwszy termin = najbliższy taki miesiąc), a nie co rok.','🏦 Usuwanie konta: opłaty, pensje i instrumenty przenoszą się na inne konto dopiero po ostatecznym „Usuń” – „Anuluj” niczego nie zmienia.','📈 Automat nie użyje ceny, która nagle różni się o ponad 40% (np. pensy zamiast funtów) – poczeka, aż potwierdzi się następnego dnia.','✍️ Wieczorne przypomnienie nie przyjdzie, gdy dziś dopisaliście wczorajsze zakupy. Wypłata zawsze 30. dnia nie jest brana za „koniec miesiąca”. PIT-28 za wspólny najem – każde odhacza swój.','🧹 Strażnik pokaże wpis zapisany dwa razy i pensję z paska policzoną podwójnie. Nowa wersja aplikacji nie przeładuje się przy otwartym pasku, wyrównaniu sald ani zamknięciu miesiąca.']},
  {v:68,title:'Decyzje po przeglądzie ✅',scene:'duo',items:['🔴 Ujemne saldo (konto bieżące, subkonto albo oszczędności) to teraz pilny punkt w 🔔 „Na dziś” i w porannym powiadomieniu – codziennie, u właściciela konta. W 👛 Kontach takie saldo jest czerwone.','⚠️ „Nie starczy na rachunki” patrzy co najmniej 7 dni do przodu (też na początek następnego miesiąca) i sprawdza wydatki roczne płacone z subkonta kopert.','🛡️ Doradca w grudniu: pieniądze na poduszkę najpierw na IKE (gotówka albo obligacje), bo limit przepada 31 grudnia. Ryczałt 17% – IKZE na pierwszym miejscu, jak przy podatku liniowym. Termometr liczy akcje świata w złotych.','🎯 Usunięty cel trafia do ⚙️ → 🛡️ „Ostatnio usunięte” i można go przywrócić.','🐱 Kotki na Budżecie rysują się raz – aplikacja działa płynniej na starszych telefonach.']},
  {v:67,title:'Poprawki z dużego przeglądu 🔧',scene:'duo',items:['🗓️ Zamknięcie miesiąca: wypłata przesunięta przez weekend (np. 20.12 w niedzielę → piątek 18.12, albo 1. dnia → 31. poprzedniego) zamyka właściwy miesiąc. „✓ Zgadza się” liczy się od początku okna zamknięcia, a pensja, która przyszła dzień wcześniej, nie liczy się dwa razy w „Czy starczy?”.','🛡️ Limity IKE i IKZE na 2027 (IKE 30 099 zł, IKZE 12 039,60 zł, dla firmy 18 059,40 zł). Gdy w nowym roku limitów brakuje, „Na dziś” o tym przypomni.','🧭 Plan doradcy zawsze sumuje się do 100% – złoto i suchy proch nie dokładają się ponad akcje.','💷 ETF-y z Londynu: automat bierze ich ceny najpierw z Yahoo (z walutą, pensy zamienia na funty), a aplikacja pilnuje, żeby cena w pensach nie zawyżyła wartości 100 razy. Przy IWDA, EIMI i VWRA podpowiada walutę USD.','🧾 Usunięty pasek pensji można przywrócić w 🗑️ „Ostatnio usunięte” – razem z wpływem, potrąceniami i PPK. Samego potrącenia albo PPK nie da się już usunąć osobno (zawyżyłoby saldo) – kotki proponują zmianę w pasku albo usunięcie całego paska.','📌 Odznaczenie opłaty stałej usuwa też jej zwroty i odsetki.','🔻 Usunięcie „spłaty całości” kredytu z banku przywraca dług.','📱📱 Dwa telefony naraz: okienko edycji konta, kategorii czy opłaty nie przesuwa już niczego na początek listy i nie przywraca usuniętej kategorii; wczytanie kopii zmienia tylko konta, kategorie i stałe – reszta zapisana chwilę wcześniej na drugim telefonie zostaje. Przydział do celu z dwóch telefonów liczy się z obu.','📝 Wpisanie planu jednej pozycji w miesiącu bez planu zaczyna od kopii ostatniego planu – reszta pozycji nie znika.','🤖 Automaty: kopia, podsumowanie miesiąca i powiadomienia mają drugą próbę, gdy GitHub pominie start; pobieranie kursów nie zawiesza się na jednym serwerze; wycena na koniec miesiąca bierze ceny z ostatniego dnia sesji, a nie z poniedziałku. Poranne powiadomienie nie powtarza codziennie spraw „⏳ Wkrótce” i ma tę samą kolejność co 🔔 w aplikacji.','🔔 Gdy automat powiadomień przestanie działać, „Na dziś” i wieczorny dymek znowu pokazują się w aplikacji.','💼 Umowa zlecenie: po przekroczeniu 120 000 zł zaliczka zostaje 12% (32% tylko, gdy złożysz wniosek – wybór w źródle dochodu), umowy do 200 zł mają ryczałt 12%, a chorobowe na zleceniu można wyłączyć.','🏦 Obligacje i lokaty: ROR i DOR liczą odsetki co miesiąc, kupony (COI, ROR, DOR) i wykup na koniec wracają na konto jako gotówka (po Belce, na IKE bez), „Wykup wcześniej” / „Zerwij” liczy opłatę, a każdy zakup obligacji może mieć oprocentowanie swojej serii. Kupony wpisują się same – nie dodawaj ich ręcznie.','🧭 Doradca: raty 0% i tanie długi (poniżej 4%) nie blokują poduszki ani IKE, przed spłatą długu najpierw mała poduszka na miesiąc, poduszka liczona wszędzie tak samo, obligacje kupowane za pieniądze spoza IKE (w IKE w XTB EDO nie kupisz), OKI z limitem 25 tys. zł na gotówkę i obligacje, ryczałt od najmu 12,5% ponad 100 000 zł.','🛡️ IKE trzymane jako konto oszczędnościowe ma limit, przypomnienia i miejsce w podsumowaniu roku – a w edycji konta podpowiedź, jak przełączyć je na „Inwestycje”.','🎨 Czytelniej: ciemniejsze napisy przy przychodach, „na styk”, podpowiedziach wykresów i w nagłówku (pastele zostają), a „🖨️ Podsumowanie roku” drukuje się do PDF z paskami i kolorami.','📅 „Rok temu” nie liczy wpisów z datą późniejszą niż dziś; „Czy starczy?” bez wspólnego konta dzieli pozycje „Wspólne” po połowie zamiast pokazywać fałszywe „zabraknie”.','🐾 Drobiazgi: kotki pamiętają o Poniedziałku Wielkanocnym, Zielonych Świątkach, Bożym Ciele, 1 i 2 listopada, 1 maja, 15 sierpnia i Trzech Królach; zmiana czasu nie przesuwa ich codziennych tekstów; przy „Mało kotków” nie ma popołudniowej ciekawostki. „1,25” w kwocie to zawsze grosze, a „1.250” – tysiąc dwieście pięćdziesiąt.','💼 Przypomnienie o pasku przychodzi w dniu, w którym pensja zwykle wpływa (wyuczonym z pasków), a pensja połączona z przychodem stałym nie daje już dwóch punktów w „Na dziś”. Rata płatna 1. przypomina się „jutro” ostatniego dnia miesiąca, a miesiąc bez wpłaty dolicza odsetki do kredytu.','👥 Przy przelewach i odhaczanych opłatach „Kto” = właściciel konta. Stały przelew między kontami w różnych walutach pyta, ile wpłynęło. Wykresy pokazują też wartości ujemne.']},
  {v:66,title:'Porządki i JDG 💼',scene:'duo',items:['💼 JDG: w źródle dochodu wybierzesz ZUS – ulga na start, preferencyjny, pełny (z chorobowym albo bez) albo własną kwotę. Podpowiedź z kwoty faktury liczy też najniższą zdrowotną, limit jej odliczenia na liniowym i próg zdrowotnej na ryczałcie (zasady 2026).','🎓 Zlecenie studenta do 26 lat – bez ZUS i zdrowotnej. Przy zleceniu z PPK koszty liczą się od przychodu razem z wpłatą pracodawcy.','👛 Konta: czyje konta pokazać – okrągłe guziki w karcie z sumą (o jeden rząd przycisków mniej), a „⚖️ Wyrównaj wszystkie salda” – pod listą kont. „Anuluj” przy wyrównaniu nie oznacza już kont jako sprawdzonych.','🐷 Oszczędności: najpierw „Ile odłożyliście” i cele, potem 🧭 Doradca i 🥧 majątek. Napis „Nieruchomości” nie jest już ucinany przy dużej czcionce.']},
  {v:65,title:'Doradca, krok 7: piaskownica 🧪',scene:'duo',items:['🧪 W karcie „🧭 Doradca” przycisk „Piaskownica”: mały kawałek na pojedyncze spółki, ETF-y tematyczne, krypto i surowce – z limitem z Waszego planu. Widać, ile już w niej jest i ile zostało miejsca.','🔎 „Co chcesz kupić?” – kotki nie mówią „kup / sprzedaj”, tylko pokazują fakty: ile to będzie portfela, czy przekroczy limit, ile tej części świata już macie przez fundusz świata, statystyki (np. tylko 4% spółek dało całą nadwyżkę ponad lokaty) i pytania adwokata diabła.','💭 Najpierw zapisujesz, dlaczego chcesz kupić i kiedy sprzedasz – z góry, na spokojnie.','⭐ Lista życzeń z ceną: gdy cena spadnie do Twojego celu, kotki dadzą znać w 🔔 Na dziś (automat pilnuje symboli).']},
  {v:64,title:'Doradca, krok 6: pilnowanie planu 🌡️',scene:'bell',items:['🌡️ W karcie „🧭 Doradca” rozwijany termometr rynku: o ile akcje świata są poniżej szczytu i względem średniej z 3 lat, oferta obligacji na tle inflacji, realna stopa dla złota i kurs dolara. Trzy stopnie: spokojnie / drogo / przecena. Tylko fakty – nie zmienia planu.','🏷️ Przy przecenie kotki przypominają Wasz list do siebie i regułę na spadki (np. „gdy akcje spadną o 25%, dokupię akcji”).','🔔 Nowe ciche przypomnienia w „Na dziś”: limit IKE w grudniu, zwrot z IKZE do zainwestowania wiosną, przegląd plan a stan co kwartał (tylko gdy coś poza widełkami), dopłata do poduszki o inflację w styczniu, kolejne transze zakupów, przegląd ankiety po roku.','🤖 Automat codziennie zapisuje cenę funduszu świata i kursy walut – historia dla termometru.']},
  {v:63,title:'Doradca, krok 5: cele 🎯',scene:'calc',items:['🌴 Emerytura: ile brakuje miesięcznie (Twoja kwota minus prognoza ZUS), jaki kapitał trzeba zebrać i ile odkładać co miesiąc – w dzisiejszych złotych, bez PPK.','🏡 Mieszkanie dla siebie: ile brakuje do wkładu i kosztów, za ile miesięcy przy obecnej nadwyżce i czy rata (z buforem banku) mieści się w 30% dochodów.','⚡ Test kryzysu w złotych: ile Wasze aktywa straciłyby w 2008, w bańce internetowej i w 2020. 💸 Strażnik kosztów: ile rocznie kosztują Wasze fundusze.','🏘️ Najem: rentowność po kosztach i ryczałcie. 🏠 Kotki sprawdzają, czy stać Was na zakup – i tylko wtedy, cicho, raz na pół roku podsuwają pomysł w 🔔 Na dziś, zawsze z „za i przeciw”.']},
  {v:62,title:'Doradca, krok 4: w co 🛒',scene:'coin',items:['🛒 Po „🐾 Policz” w „💸 Gdzie wpłacić” jest teraz „W co”: kotki dzielą kwotę tak, żeby dokupić to, czego brakuje w Waszym planie (np. obligacji, gdy akcje urosły), i podają konkretny fundusz z Waszej listy (z ISIN), ile jednostek kupić i ile kosztuje wymiana waluty w XTB (0,5%).','📅 Dużą kwotę w akcje (ponad 10% części długoterminowej) kotki rozkładają na 4–12 zakupów, raz w miesiącu.','🧮 Kalkulator obligacji: która obligacja da najwięcej za rok, 2, 3, 4 albo 10 lat – po podatku i opłacie za wcześniejszy wykup.','💾 Poradę można zapisać – aplikacja sama ją odhacza, gdy wpiszecie zakup funduszu albo przelew na IKE/IKZE. Jest też przycisk do ustawienia stałego przelewu na inwestycje.']},
  {v:61,title:'Doradca, krok 3: gdzie wpłacić 💸',scene:'coin',items:['💸 W karcie „🧭 Doradca” przycisk „Chcę zainwestować…”: wpisujesz kwotę i odpowiadasz na kilka krótkich pytań (skąd pieniądze, na jaki cel, czy mogą być potrzebne w 3 lata). Kotki dzielą kwotę: najpierw długi i poduszka, potem IKZE albo IKE – zależnie od progu podatkowego i limitów – nadpłata kredytu według ankiety, na końcu zwykły rachunek.','👥 „Wspólnie” dzieli kwotę między Was dwoje: najpierw IKZE osoby z wyższym progiem, potem IKE obojga.','⚖️ Porównanie IKE / IKZE / zwykłe konto w złotych do 65. roku życia i lista „🚫 Na pewno nie tu” z powodami.','🔍 Każdy z 4 kafelków doradcy można stuknąć – pokazuje szczegóły: konta poduszki, długi, każde IKE i IKZE osobno (limit, wpłacone, zostało) i plan.']},
  {v:60,title:'Doradca, krok 2: ankieta i plan 🎯',scene:'calc',items:['🧭 W Oszczędnościach nowa karta „Doradca”: ile miesięcy starczy poduszka, czy są długi do spłaty najpierw, ile zostało limitu IKE/IKZE na ten rok i Wasz plan.','📝 Kotki prowadzą ankietę – jedno pytanie na ekranie, „Nie wiem” zawsze można. Pytania pojawiają się tylko, gdy mają sens; odpowiedzi zapisują się od razu, można przerwać i wrócić. Na początek ankieta jest tylko u Matiego – w planie jest przycisk „Pokaż ankietę Werci”.','📄 „Plan na jednej kartce”: ile akcji, obligacji, złota i gotówki, z widełkami, ile moglibyście stracić w kryzysie jak 2008 (w złotych), poduszka, odkładanie, reguła na spadki i list do siebie. Zatwierdzasz albo zmieniasz.','🎯 Pod kołem majątku paski „jest / ma być”, a kotki podpowiadają, co dokupić przy następnej wpłacie. Bez sprzedawania i bez zgadywania przyszłości.']},
  {v:59,title:'Doradca, krok 1b: nieruchomości i inne aktywa 🏠',scene:'duo',items:['🏠 W karcie „🥧 Z czego składa się majątek” są przyciski „🏠 ＋ Nieruchomość” i „✨ ＋ Inne aktywo” (np. kolekcja, działka, udziały). Wpisujecie wartość i datę wyceny, przy nieruchomości – czy mieszkacie, wynajmujecie, czynsz i kredyt z 🔻.','🏡 Mieszkanie, w którym mieszkacie, jest w majątku osobno: nie zarabia, więc nie wchodzi do proporcji. Główne koło pokazuje 🏠 nieruchomości, które pracują, i 📈 aktywa – stuknięcie otwiera szczegóły.','👥 Przy wspólnych rzeczach wpisujecie udział (jak w akcie notarialnym). W zakładce osoby liczy się jej udział – wartości i kredytu. W 👛 Kontach nieruchomości są obok zobowiązań, salda się nie zmieniają.','🔔 Raz na rok–trzy lata kotki cicho przypomną o nowej wycenie.']},
  {v:58,title:'Doradca, krok 1: z czego składa się majątek 🥧',scene:'coin',items:['🥧 W 💰 Majątek → Oszczędności nowa karta „Z czego składa się majątek”: koło pokazuje, ile macie w gotówce, obligacjach, akcjach, złocie i innych aktywach – w złotych i w procentach. Stuknij kawałek, żeby zobaczyć, co w nim jest. PPK się nie liczy.','🏷️ Każdy instrument i konto ma klasę (np. „Akcje – cały świat”, „Obligacje indeksowane”). Przypisuję ją sam; stuknięcie pozycji pozwala zmienić. Można dodać „＋ Własną klasę” (np. zegarki).','🔎 Karta „Analiza funduszy”: czy Wasze ETF-y spełniają kryteria (tanie, akumulujące, duże), czy któryś się nie dubluje, i lista 7 funduszy z XTB. Fundusz spoza listy też jest śledzony – kotki zapytają tylko, w co inwestuje.']},
  {v:57,title:'Kto ile wydał i podpowiedzi 💡',scene:'duo',items:['🧾 Karta „👥 Czy starczy?” pokazuje przy każdej osobie, ile z jej części planu już wydała ze swoich kont (np. „z planu wydane 1 200 z 2 000 zł”), a po rozwinięciu – pozycje ponad tę część ▲.','💡 Gdy ktoś zapłaci swoją kartą za coś wspólnego (albo za część drugiej osoby), aplikacja to zauważy: wspólnym zostaje mniej do wydania, a podpowiedź mówi, ile można sobie oddać ze wspólnego konta. Nic nie przelewa się samo.','💡 Gdy na wspólnych ma zabraknąć, karta (i 🔔 Na dziś) podpowiada, ile dołożyć po połowie.']},
  {v:56,title:'Czy starczy – prawdziwe kwoty 🟡',scene:'duo',items:['💰 Karta „👥 Czy starczy?” pokazuje teraz prawdziwy przewidywany stan kont na koniec miesiąca – bez odejmowania zapasu (zapas zostaje tylko w kaskadzie nadwyżek).','🎨 Kolory: ✅ powyżej 300 zł, 🟡 na styk – w którymś dniu mniej niż 300 zł, ⚠️ poniżej zera. Punkt w 🔔 Na dziś tylko przy ⚠️.']},
  {v:55,title:'Czy starczy – od tego, co na kontach 💰',scene:'duo',items:['💰 Karta „👥 Czy starczy?” liczy teraz od tego, co jest już na Waszych kontach i subkontach. Do tego dodaje to, co jeszcze wpłynie, i odejmuje to, co jeszcze wyjdzie według planu. Wynik: ile zostanie każdemu na koniec miesiąca.','🛒 Z planu liczy się tylko to, czego jeszcze nie wydaliście: plan pozycji minus to, co dana osoba już na nią wydała ze swoich kont.','📉 „Najmniej”: dzień, w którym na kontach będzie najmniej, np. tuż przed wypłatą albo zanim wpłyną przelewy na wspólne. Jeśli wtedy zabraknie, będzie ⚠️ i cichy punkt w 🔔 Na dziś.','🛟 Na każdym koncie bieżącym zostaje zapas, ten sam co w kaskadzie nadwyżek (domyślnie 250 zł). ✅ znaczy: starczy i zapas zostaje.','📅 Przyszły miesiąc zaczyna się od przewidywanego stanu kont na koniec bieżącego.']},
  {v:54,title:'Czy każdemu starczy? 👥',scene:'duo',items:['👥 Przy każdej pozycji wydatków w Budżecie jest nowy przycisk „Płaci”: Mati, Wercia, Wspólne, po połowie albo inny podział (suwak). Z „?” to podpowiedź z ostatnich 3 miesięcy, czyli z czyich kont szły wydatki. Stuknij, żeby ustawić na stałe albo tylko na ten miesiąc.','📌 Opłaty stałe liczą się same temu, z czyjego konta schodzą. „Płaci” dotyczy tylko reszty planu pozycji.','👥 Na dole Budżetu jest karta „Czy starczy?”: osobno Mati, Wercia i wspólne konta. Wpływa: pensje (zanim wpłyną – kwota ostatniej wypłaty), przychody stałe i przelewy od drugiej osoby. Wychodzi: opłaty stałe, Wasza część planu, przelewy na wspólne, do drugiej osoby i na oszczędności. Stuknij osobę, żeby zobaczyć szczegóły.','🔔 Gdy według planu komuś zabraknie, w „Na dziś” pojawi się cichy punkt (bez powiadomienia). To samo zestawienie jest w 🗓️ zamknięciu miesiąca, w kroku „Plan”.']},
  {v:53,title:'Bez minusa – do końca 🚫',scene:'lupa',items:['🚫 Minus na koncie nie przejdzie też „od drugiej strony”: przy zmniejszeniu albo usunięciu wpływu (pensji spoza paska, przelewu na konto, zwrotu), przesunięciu go na późniejszy dzień albo inne konto, odznaczeniu przychodu stałego i przy „↩️ Przywróć” / „Cofnij” wydatku, gdy te pieniądze są już wydane. Kotki powiedzą, na którym koncie i ile by brakowało – nic się wtedy nie zmienia.','📈 Analiza → Rok → „Wasza inflacja” w trwającym roku porównuje te same dni: bieżący miesiąc do dziś z tym samym miesiącem rok temu do tego samego dnia (wcześniej kilka dni porównywało się z całym miesiącem).','🖨️ Podsumowanie trwającego roku porównuje wydatki z tymi samymi dniami poprzedniego roku, a nie z całym rokiem.']},
  {v:52,title:'Bez minusa na koncie 🚫',scene:'lupa',items:['🚫 Wydatek albo przelew, po którym konto zeszłoby poniżej zera, się nie zapisze – na prawdziwym koncie nie może być minusa. Kotki powiedzą, na którym koncie i ile by brakowało, i poproszą o przeanalizowanie kont: może brakuje wpisanego wpływu albo saldo różni się od banku (⚖️ Wyrównaj wszystkie salda naraz).','To samo przy odhaczaniu opłat i stałych przelewów, zapłacie wydatku rocznego, spłacie długu i pożyczce dla kogoś. Liczą się konta bieżące, subkonta i oszczędności – także wpis z wcześniejszą datą nie może zrobić minusa w żadnym późniejszym dniu.','🪙 Drobne odkładają się tylko wtedy, gdy na koncie są na nie pieniądze.']},
  {v:51,title:'Poprawki po czwartym przeglądzie 🔎',scene:'lupa',items:['📅 Wydatki z „Roczne i terminy” płacone co kwartał albo co miesiąc znowu przypominają się w porę – zapłata z poprzedniego kwartału czy miesiąca nie ukrywa już następnej.','📈 Gdy serwis z cenami akcji i ETF-ów jednego dnia nie odpowie, automat zostawia ostatnią znaną cenę – wycena nie spada wtedy do ceny zakupu (także w wycenie na koniec miesiąca).','🤖 Ostrzeżenie „Automat nie pobiera danych” pojawi się także wtedy, gdy automat działa, ale od 3 dni roboczych nie dostaje kursów.','🌍 Zwrot na koncie w euro pokazuje euro, a nie złote, i musi wpłynąć na konto w tej samej walucie; okienka odhaczania pokazują walutę konta.','✍️ Wieczorne przypomnienie „Już 20:00…” liczy wpisy tak samo jak „Na dziś” i powiadomienie.','🧹 Drobne porządki w kodzie i w kolorach (jeden odcień szarych podpisów).']},
  {v:50,title:'Porządki po przeglądzie 🧹',scene:'lupa',items:['📧 Mail z podsumowaniem miesiąca jest dużo dokładniejszy: krótkie wnioski na górze, porównanie z poprzednim miesiącem, ze średnią i z tym samym miesiącem rok temu, plan a rzeczywistość, kategorie, największe wydatki, sklepy, Mati ↔ Wercia, oszczędności, cele i to, co czeka w nowym miesiącu.','✓ Odznaczenie opłaty stałej najpierw pyta: „Usunąć wpis?” – przypadkowe stuknięcie niczego już nie skasuje.','🔗 Usuwane konto, którego jeszcze coś używa (opłata, pensja, drobne, PPK…), od razu pozwala wybrać konto, na które to przenieść.','🏠 PIT-28 za najem przypominam do 30 kwietnia (tak jest od 2023 r.).','📅 Edycja wydatku rocznego „co miesiąc” nie zmienia go już na „co rok”, a usunięcie zapłaty cofa kopertę. Podsumowanie roku liczy też konta z archiwum.','🔁 Stały przelew na konto wspólne to „Przelano”, a nie „Odłożono 🐷”. Wercia: bez kwiatka przy nazwie miesiąca 🌸']},
  {v:49,title:'Poprawki i wpisy pozycji 🔎',scene:'lupa',items:['🔎 W Budżecie stuknij nazwę pozycji (np. „Zakupy spożywcze ›”) – zobaczysz wszystkie jej wpisy z miesiąca, plan i ile wydano. Stuknięcie wpisu go otwiera, „＋ Dodaj” dopisuje nowy do tej pozycji.','🗓️ Zamknięcie miesiąca przy wypłacie pod koniec miesiąca proponuje teraz plan na następny miesiąc (zamykając październik – plan na listopad), a nie na zamykany.','🔢 Przy największym tekście (A++) kwoty w kafelkach Budżetu nie są już ucinane „…”.','👥 Podpowiedzi „Dodać do stałych opłat / przelewów?” widzi tylko właściciel konta, z którego idą pieniądze (ze wspólnego – oboje).','ⓘ Długie objaśnienia (poduszka, FIRE, odsetki, kaskada, koperty roczne, zamknięcie miesiąca) schowały się pod małe „ⓘ” – stuknij, żeby przeczytać.','„Skopiuj plan z poprzedniego miesiąca” pokazuje się tylko, gdy miesiąc nie ma jeszcze planu.']},
  {v:48,title:'Rok temu, subskrypcje i licznik 📊',scene:'calc',items:['📅 Analiza → Miesiąc: nowa karta „Rok temu” – przychody, wydatki i odłożone w porównaniu z tym samym miesiącem rok wcześniej i 3 kategorie, które zmieniły się najbardziej. Pojawi się, gdy będą wpisy sprzed roku.','📋 Raz w roku „Na dziś” zaprosi do przeglądu subskrypcji: lista z kosztem rocznym i przyciski „Zostaje”, „Zmień” i „Rezygnuję”. W każdej chwili: 📌 Stałe → „📆 Opłaty stałe w roku” → „📋 Przejrzyj”.','📊 ⚙️ → 📖 Pomoc → „Czego używamy”: aplikacja liczy, które ekrany, przyciski i karty otwieracie (każde z Was osobno) i pokazuje, czego nikt nie używa od 3 miesięcy. Liczby są tylko w Waszym Firebase. Za 2–3 miesiące zdecydujemy, co uprościć.']},
  {v:47,title:'Porządek: najpilniejsze na górze ⏳',scene:'bell',items:['🔔 „Na dziś” układa sprawy według pilności: najpierw to, co po terminie, potem na dziś i na jutro. Rzeczy na za kilka dni (koniec umowy, promocji, gwarancji, wykup obligacji, przypomnienie albo termin wydatku rocznego, PIT przed 20 kwietnia) czekają niżej pod „⏳ Wkrótce” – zwinięte. Liczba przy dzwonku liczy tylko to, co jest na dziś.','🐷 Oszczędności w nowej kolejności: „Ile odłożyliście” i cele na górze, FIRE i wykres „Wpłacone a wartość” na dole. W zakładkach osób cele są zaraz pod przyciskami. Odsetki z kont – w jednej linijce.','📌 W Stałych opłaty są na górze, przychody stałe (najem) na dole – a gdy ich nie macie, zostaje mały przycisk.','🐾 Kotki na Budżecie nie powtarzają już „odłożyliście…”, bo mówi to pasek 🐷 tuż pod nimi.','🧪 W wersji demo są przykładowe wydatki roczne (OC, ubezpieczenie mieszkania, przegląd, prezenty) i terminy (szczepienie kotów, opony).']},
  {v:46,title:'Wszystkie sprawy w dzwoneczku 🔔',scene:'bell',items:['🔔 Budżet bez kolorowych ramek: „Do odhaczenia”, zamknięcie miesiąca, koperty roczne, kopia danych, „Do zaplanowania” i „Plan niższy niż opłaty stałe” są teraz tylko w „Na dziś” (dzwonek w nagłówku). Liczba przy dzwonku pokazuje, ile czeka.','📊 Przekroczony plan i „zostało mniej niż 15%” też są w dzwonku – z przyciskiem „Wiem”.','📌 W Stałych podpowiedzi „Dodać do opłat stałych?” też są w dzwonku.','🐾 Kotki na Budżecie już tylko się witają, chwalą i opowiadają ciekawostki.','🪙 „W tym z drobnych” w Oszczędnościach liczy tylko drobne, które trafiły na konta oszczędnościowe, i pokazuje resztę wpłat.']},
  {v:45,title:'Kwiatki dla Werci 🌸',scene:'heather',items:['Na telefonie Werci w różowym kolorze rozkwitła wiosna: gałązka przy powitaniu kotków, kwiatek przy miesiącu i pod wybraną zakładką, kwiatki w kafelkach ustawień, w okienku wpisu, w Analizie i przy pustych ekranach.','🎯 Cele rosną jak łodyżka – na 100% zakwitają. Zamiast konfetti spadają płatki wiśni.','Kolor zmienisz w ⚙️ → 📱 Ten telefon → 🎨 Wygląd. Na telefonie Matiego nic się nie zmienia.']},
  {v:44,title:'Ustawienia w kafelkach ⚙️',scene:'duo',items:['⚙️ Ustawienia to teraz 6 kafelków: 🏦 Konta · 🗂️ Kategorie i drobne · 📱 Ten telefon · 🛡️ Bezpieczeństwo · 🤖 Automaty · 📖 Pomoc.','Stuknij kafelek – otworzy się tylko ta część. „‹ Ustawienia” (albo ⚙️) wraca do kafelków. Nic nie rozwija się samo.']},
  {v:43,title:'Każde ma swoje – część 2 👥',scene:'duo',items:['🔔 Na ekranie głównym, w „Na dziś”, w dymku kotków i w powiadomieniach każde widzi tylko swoje sprawy i wspólne: opłaty stałe, paski, raty, odsetki, koniec umowy, najem, „nie starczy na rachunki”.','👥 Czyje to jest, wynika z „👥 Dotyczy” w opłacie, a gdy puste – z konta. Płacisz swoją opłatę ze wspólnego konta? Ustaw „Dotyczy” na siebie.','📅 Wydatki roczne i 🔔 przypomnienia też mają „👥 Dotyczy” – np. OC Twojego auta albo fryzjer. Puste = wspólne, przypomina obojgu.','🤖 Sprawy techniczne (kopia danych, automat, limity IKE/IKZE) – tylko u Matiego.','W 📌 Stałe nadal widać wszystko – przełącznikiem Wszystkie · Mati · Wercia · Wspólne.']},
  {v:42,title:'Każde ma swoje 👥',scene:'duo',items:['👥 W 📌 Opłatach na górze: Wszystkie · Mati · Wercia · Wspólne – widać tylko opłaty, przychody i przelewy stałe wybranej osoby. Czyje są, wynika z konta, z którego idą; w edycji opłaty jest też „👥 Dotyczy”, gdy np. Twój telefon płaci konto wspólne.','🔒 Bailey i Ivo raz zapytają, czyj jest login – potem ten telefon zawsze podpisuje wpisy właściwą osobą i nie da się jej przestawić przypadkiem.','🙀 Wpis z konta drugiej osoby? Kotki zapytają, czy na pewno. „Tak, wiem” – do końca dnia nie pytają o to konto. Konta wspólne i przelewy na konto drugiej osoby – bez pytania.']},
  {v:41,title:'Szybciej i porządniej ⚡',scene:'ivoHappy',items:['⚡ Po zapisie ekran odświeża się raz zamiast dwa–trzy razy (potwierdzenie z serwera zmienia już tylko napis „zsynchronizowano”). Sprawdziliśmy też aplikację na 15 000 wpisów – działa płynnie.','🧹 Porządki w środku aplikacji: mniej starego kodu, który już nic nie robił. Wasze dane są nietknięte.']},
  {v:40,title:'Odsetki z kont 💰',scene:'coin',items:['💰 Przy koncie oszczędnościowym (i subkoncie) jest „💰 Oprocentowanie”: stawka, promocja (do kiedy i do jakiej kwoty), kiedy bank dopisuje odsetki i jak z podatkiem.','🧮 Odsetki liczę dzień po dniu od salda – wpłata z połowy miesiąca zarabia pół miesiąca. Z podatkiem Belki 19%, bez niego przy IKE, IKZE i OKI. Bank zagraniczny (np. Revolut)? „Rozliczam sam” – w marcu przypomnę, ile wpisać w PIT-38.','🔔 W dniu dopisania odsetek „Na dziś” pokaże gotową kwotę – „Wpisz” i ewentualnie popraw grosze z wyciągu. Odsetki to zysk, nie „odłożone”.','🎁 2 tygodnie przed końcem promocji przypomnę, żeby przenieść pieniądze. W Oszczędnościach nowa karta „Odsetki z kont”.']},
  {v:39,title:'Ciekawostki od kotków 🐾',scene:'lupa',items:['🐾 Gdy kotki ostrzegają (opłata po terminie, przekroczony plan, blisko limitu), pod dymkiem jest „Rozumiem, kociaki”. Uwaga znika do jutra na tym telefonie – chyba że coś się zmieni, np. dojdzie kolejna opłata po terminie.','📚 Zamiast uwagi – ciekawostka dnia o budżecie, oszczędzaniu i inwestowaniu. Jest ich 366, na każdy dzień roku inna (29 lutego – specjalna), na obu telefonach ta sama. Po południu kotki pokazują ją same.','🎄 W święta i urodziny – życzenia i nazwa dnia (doszły m.in. Wigilia, Mikołajki, 11 Listopada, 3 Maja, Dzień Dziecka i Dzień Oszczędzania).','💬 Dymki są wyraźniejsze: najpierw konkret z kwotą (pogrubiony), potem żart.']},
  {v:38,title:'Pewniejsza kopia i poprawki 🛠️',scene:'lupa',items:['💾 Kopia (z ⚙️ i z maila) zapisuje teraz wszystko: także ustawienia kaskady, schowane podpowiedzi, subkonto kopert rocznych, wpisaną inflację, limity IKE/IKZE, urodziny i zamknięcia miesięcy. Po wczytaniu aplikacja wraca dokładnie do stanu z kopii.','📅 Wydatki „co kwartał” i „co miesiąc” po zapłacie znowu wchodzą do planu w kolejnym terminie, a wpis przez ＋ podpowie „To ta opłata?”.','🔁 Wpis przeniesiony na inny miesiąc zachowuje wszystkie powiązania, a po usunięciu zawsze jest w „Ostatnio usunięte”. Wpis z konta w archiwum pokazuje to konto.','🔄 Nowa wersja aplikacji pobiera się w tle w całości i dopiero wtedy się włącza – słaby internet niczego nie popsuje. 🔍 🔔 ⚙️ stoją równo.']},
  {v:37,title:'Zamknięcie przed wypłatą 💧',scene:'lupa',items:['🗓️ Każde z Was ma własne zamknięcie miesiąca – dzień przed swoją wypłatą. Dzień wypłaty aplikacja zna sama z wpisanych pasków (koniec miesiąca, weekend → piątek). „Co było ponad plan” i „Plan” są wspólne.','💧 Kaskada liczy nadwyżkę dzień przed wypłatą – wtedy na koncie jest to, co naprawdę zostało. W środku miesiąca nie proponuje przelewu pieniędzy na zakupy, a nowej pensji nigdy nie liczy jako nadwyżki.','⚠️ Nowe w „Na dziś”: „nie starczy na rachunki” – gdy na koncie zabraknie na opłatę stałą przed terminem, z przyciskiem „Przelej”.','🔁 Stały przelew może iść też na konto wspólne albo do drugiej osoby. Powtarzający się przelew sam podpowiem.','🛟 Poduszka nie jest już pulą na cele. 📝 Plan po zamknięciu – ze średniej z 3 miesięcy. 🧾 Rejestr w dwóch linijkach. ⚖️ Salda wyrównujecie wszystkie naraz.']},
  {v:36,title:'Zamknięcie miesiąca 🗓️',scene:'lupa',items:['🗓️ W pierwszych dniach miesiąca na Budżecie i w „Na dziś” czeka „Zamknij wrzesień” – 5 kroków, ok. 10 minut: salda z bankiem, co było ponad plan, nadwyżka, plan na nowy miesiąc i cele.','🏦 Przy każdym koncie widać, kiedy ostatnio sprawdzaliście saldo z bankiem. „✓” – zgadza się, „⚖️” – wpisz saldo z banku.','👫 Kroki możecie podzielić – odhaczone widać na obu telefonach. 1. dnia miesiąca przypomnę powiadomieniem. Zawsze możecie zajrzeć: przycisk na dole Budżetu.']},
  {v:35,title:'Uczciwe porównania i krótszy Rejestr ⏳',scene:'lupa',items:['⏳ W trwającym miesiącu Analiza porównuje z poprzednim miesiącem do tego samego dnia (np. 1–25 października z 1–25 września), a nie z całym miesiącem – strzałki nie chwalą już za wcześnie.','📊 „Zmieściło się” i „wyraźnie mniej niż plan” pokażę po końcu miesiąca. W trakcie widać to, co już przekroczone albo poza planem.','🧾 Rejestr: wyszukiwarka i okres na górze, reszta filtrów pod przyciskiem „⚙️ Filtry”. Przy każdym dniu suma wydatków.']},
  {v:34,title:'Jeden rachunek – jeden wpis 📌',scene:'bell',items:['📌 Gdy wpiszesz przez ＋ rachunek, który jest w opłatach stałych (np. Netflix) albo w wydatkach rocznych (np. OC), zapytam: „To … z opłat stałych?” – jedno „Tak” i rachunek jest odhaczony, bez przypominania.','✓ Gdy odhaczasz opłatę, a ktoś już ją wpisał przez ＋, zaproponuję „Połącz z tym wpisem” zamiast drugiego wydatku. W 📌 Stałe i w „Na dziś” widać „💡 jest podobny wpis”.','📊 Budżet ostrzega, gdy plan pozycji jest niższy niż jej opłaty stałe (np. po podwyżce czynszu) – „Podnieś plan do opłat stałych”.']},
  {v:33,title:'Urodziny i ulga dla młodych 🎂',scene:'celebrate',items:['🎂 Bailey i Ivo zapytają o Twoją datę urodzenia (każde z Was na swoim telefonie). W dniu urodzin złożą Ci życzenia – w aplikacji i rano w powiadomieniu – a drugiej osobie przypomną o życzeniach. Datę zmienisz w ⚙️ → „Kto korzysta z tego telefonu?”.','🎓 Ulga dla młodych liczy się sama: do 26. urodzin pensja z umowy o pracę i zlecenia jest bez podatku (do 85 528 zł w roku, ze wszystkich umów razem). „Podpowiedz z brutto” i „z netto” to uwzględniają, ZUS i zdrowotna zostają bez zmian.','🎓 Miesiąc przed 26. urodzinami przypomnę w „Na dziś”, że wypłaty będą niższe – i o ile mniej więcej.']},
  {v:32,title:'Roczne i terminy, porządki 🧹',scene:'bell',items:['📅 Przypomnienia i wydatki roczne są teraz w jednej zakładce „Roczne i terminy” (📌 Stałe). Jeden przycisk „+ Dodaj” z gotowymi: OC, ubezpieczenie, przegląd, opony, szczepienie kotów. Z kwotą – odkładanie, bez – samo przypomnienie. Zawsze ok. 2 tygodnie przed terminem.','🏠 Najem: przy przychodzie stałym przypomnę o ryczałcie (z kwotą) i o PIT-28. 🧾 Od 1 marca przypomnienie o PIT dla każdego z Was.','💧 Kaskada nadwyżek zostawia 250 zł na koncie, mówi, ile zostało w planie do końca miesiąca, i nigdy nie proponuje PPK ani gotówki.','⚙️ Ustawienia w grupach. Wartości inwestycji aktualizujesz w jednym miejscu: „📈 Aktualizuj wartości” (albo robi to automat). Bez pliku do kalendarza i starych wpisów inwestycji.']},
  {v:31,title:'Lepsze planowanie 📝',scene:'papers',items:['📅 Wydatki roczne same wchodzą do planu w miesiącu płatności (np. OC w marcu) – i nie kopiują się na kolejny miesiąc. W Budżecie pod pozycją widać „📅 do planu doliczone”.','📊 Analiza → Rok → „Plan a rzeczywistość”: pozycje, które prawie co miesiąc przekraczają plan (albo są dużo poniżej), z przyciskiem „Ustaw … od listopada”.','🙈 Pozycje i całe kategorie można ukryć (⚙️ → Kategorie → stuknij pozycję). Znikają z Budżetu i z wpisywania, historia zostaje. Pozycji z wpisami nie da się już usunąć – tylko ukryć.']},
  {v:30,title:'Prawdziwe liczby 🐷',scene:'coin',items:['🐷 „Odłożone” to teraz tylko to, co naprawdę przelaliście na oszczędności i inwestycje (z PPK). Wzrost albo spadek kursów pokazuję osobno: „inwestycje zarobiły / straciły”. Tak samo w mailu i w podsumowaniu roku.','📊 W Budżecie, pod kafelkami, widać „Odłożone w tym miesiącu” i ile to z Waszego celu.','🛟 Jedna karta poduszki: liczę tylko konta oszczędnościowe – bez IKE, IKZE, PPK i inwestycji, których nie da się szybko wypłacić. Cele-koperty też już nie liczą IKE, IKZE i PPK.','💑 Mati ↔ Wercia: wydatki według tego, czyje było konto – z konta wspólnego trafiają do „Wspólne”.']},
  {v:29,title:'Pensje prościej 💼',scene:'calc',items:['🧮 Nie masz jeszcze paska? W pasku stuknij „Podpowiedz z netto” i wpisz, ile wpłynęło na konto – brutto, ZUS, zdrowotną, podatek i PPK policzę orientacyjnie (PPK możesz wyłączyć w danym miesiącu).','✂️ Przy źródle dochodu zapytam, co jest potrącane od razu z pensji (np. ubezpieczenie grupowe, Multisport). Potrącenia wpisują się same w każdym nowym pasku i trafiają do budżetu.','➕ W 💼 Pensje jest „+ Inny przychód” i lista przychodów spoza pasków (sprzedaż rzeczy, premia, zwrot PIT, najem).','👯 Gdy ta sama pensja miałaby się wpisać dwa razy (z paska i z 📌 Stałe), aplikacja zapyta.']},
  {v:28,title:'Pewniej i szybciej 🛡️',scene:'lupa',items:['👯 Gdy wpisujecie ten sam paragon drugi raz (ta sama kwota, dzień i sklep), aplikacja zapyta: „Taki wpis już jest – zapisać mimo to?”.','💾 Co miesiąc, po wysłaniu kopii mailem, robot wczytuje ją na próbę i sprawdza wszystkie wpisy i salda. Gdyby coś było nie tak, dostaniesz maila od GitHuba.','🧾 W styczniu przypomnę, żeby zaktualizować zasady pensji (ZUS, progi) na nowy rok.','⚡ Aplikacja liczy szybciej przy wielu latach danych – sprawdzone na 18 000 wpisów (10 lat).']},
  {v:27,title:'Drobne szlify wyglądu 🎨',scene:'happy',items:['Przyciski „+ …”, „+ / −” przy kwocie i „Podziel paragon” są teraz w kolorze Twojego telefonu.','Stałe przelewy: „Przelane 1 z 1”. Pusta zakładka „🔻 My winni” nie pokazuje już karty z zerami. Analiza → Rok: przy „Zostało w roku” średnia miesięczna.']},
  {v:26,title:'Szybciej i pewniej ✍️',scene:'papers',items:['✍️ Przy notatce pojawiają się podpowiedzi – Wasze najczęstsze sklepy i miejsca. Jedno stuknięcie wpisuje nazwę (i podpowiada pozycję). Te same nazwy = dokładniejsze „🏪 Gdzie wydajemy”.','📷 Gdy zakup ma gwarancję, w okienku jest „Dołącz zdjęcie paragonu”. Na liście gwarancji widać 📷 przy zakupach ze zdjęciem.','🙈 Przytrzymaj nazwę miesiąca w nagłówku – tryb dyskretny włącza się i wyłącza.','🤖 Robot sprawdza teraz także obliczenia: pensje, obligacje, raty, salda.']},
  {v:25,title:'Zdjęcia paragonów 📷',scene:'envelope',items:['W okienku wpisu na dole: „📷 Zdjęcie paragonu” – zrób zdjęcie albo wybierz z galerii (do 3 przy jednym wpisie). Przyda się przy reklamacji i gwarancji.','Telefon sam zmniejsza zdjęcie do ok. 100–180 KB, paragon dalej jest czytelny. Zdjęcia leżą w Waszej bazie Firebase w darmowym limicie (1 GB = kilka tysięcy zdjęć) – nic nie trzeba płacić.','Stuknij miniaturkę, żeby powiększyć albo zapisać w telefonie. W Rejestrze wpis ze zdjęciem ma 📷.','⚙️ → Kopia danych: ile miejsca zajmują zdjęcia i „📷 Pobierz kopię ze zdjęciami” (comiesięczny mail z kopią ich nie zawiera).']},
  {v:24,title:'Umowy, koszt roczny i sklepy 🏪',scene:'calc',items:['📄 Opłata stała → „Umowa do…”: 2 miesiące przed końcem umowy (internet, telefon, OC) przypomnę w „Na dziś”, żeby porównać oferty albo negocjować. „Załatwione” chowa przypomnienie.','📆 W 📌 Stałe widać, ile opłaty stałe kosztują w roku – osobno subskrypcje i wydatki roczne.','🏪 Analiza (Pełna) → „Gdzie wydajemy”: sklepy i miejsca z notatek – ile, ile razy i średnio za jednym razem, w miesiącu i w roku.']},
  {v:23,title:'Ostatnio usunięte i tryb dyskretny 🙈',scene:'box',items:['🗑️ ⚙️ → „Ostatnio usunięte”: wpisy usunięte w ostatnich 60 dniach, z przyciskiem „↩️ Przywróć” (wraca razem ze zwrotami, PPK i odsetkami).','🙈 ⚙️ → Wygląd → „Ukryte”: wszystkie kwoty jako „•••”, gdy pokazujecie komuś telefon. Pasek „Pokaż kwoty” na górze wyłącza tryb.','🚫 Podwójne stuknięcie nie przybliża już ekranu. Przybliżyć można dwoma palcami.']},
  {v:22,title:'Porządki po przeglądzie ✨',scene:'lupa',items:['Analiza → Rok: średnie „/mies.” liczą się od pierwszego miesiąca z wpisami (wcześniej dzieliły przez wszystkie miesiące od stycznia i wychodziły za niskie).','Kwoty od 1000 zł zawsze z odstępem („5 449,18 zł”), kolor telefonu także w okienku nowego wpisu, jednakowe przyciski propozycji, „+ …” zawsze wielką literą.','Na wąskim telefonie z dużym tekstem: tabela „Miesiąc po miesiącu”, filtr „▲ Ponad plan” i „+ Przelew” mieszczą się w jednej linijce; napisy w „Przepływie pieniędzy” nie nachodzą na siebie.','💰 Majątek: „👛 Konta” → „🏦 Salda / 🔻 My winni / 🔺 Nam winni”. Nowy wpis na telefonie bez historii ustawia konto osoby telefonu.','Bailey: zamknięte oko na brązowej łacie jest teraz widoczne. 🤖 Każdą zmianę aplikacji sprawdza najpierw robot na GitHubie.']},
  {v:21,title:'Raty liczą się same 🔻',scene:'calc',items:['👛 Konta: stan kont nie jest już pomniejszany o zobowiązania. Obok widać osobno „🔻 do spłaty” i „🔺 pożyczone innym”.','Wpisz przy zobowiązaniu oprocentowanie nominalne (nie RRSO) i wybierz raty równe albo malejące – aplikacja policzy ratę, ile z niej to odsetki, koniec spłaty i odsetki do końca.','„+ Rata” sama wpisuje podpowiedzianą kwotę – zmienisz ją, jeśli bank pobrał inną. Bez oprocentowania dzieli to, co zostało, na równe części do końca.','W dniu raty 🔔 „Na dziś” przypomni: „Rata: … – ok. 803,44 zł”.']},
  {v:20,title:'Odkładanie na spłatę pożyczki 💰',scene:'coin',items:['🔻 My winni → Edytuj → „💰 Zbieram na spłatę całości na koncie”: wybierz konto, na które odkładasz. Na jedno konto możesz zbierać na kilka pożyczek.','Na karcie pożyczki widać „odłożone” i pasek. „💰 Odłóż” otwiera przelew, a w przelewie wpisujesz, ile idzie na którą pożyczkę. Stały przelew w 📌 Stałe też możesz przypisać do pożyczki.','Potrzebujesz pieniędzy na życie? „↑ Weź z odłożonych” – licznik spadnie i nic się nie rozjedzie. Strażnik ostrzeże, gdy na koncie jest mniej, niż odłożono.','„✅ Spłać całość”: spłata kapitału nie liczy się w Budżecie (to oddanie pożyczonych pieniędzy), a odsetki trafiają do Budżetu z dopiskiem „Odsetki od spłaty pożyczki”.']},
  {v:19,title:'Podsumowanie roku 🖨️',scene:'papers',items:['📈 Analiza → Rok → „🖨️ Podsumowanie roku”: cały rok na jednej stronie – przychody, wydatki, miesiąc po miesiącu, kategorie, majątek, IKE/IKZE/PPK i ulgi do PIT.','Przycisk „Zapisz jako PDF / drukuj” zapisze ją jako plik albo wydrukuje.','1 stycznia automat wyśle Wam obojgu podsumowanie poprzedniego roku mailem.','W Rejestrze znów widać wszystkie filtry (zakres, rodzaj, osoba, konto, kategoria).']},
  {v:18,title:'Wersja demonstracyjna 🧪',scene:'wink',items:['Chcesz komuś pokazać aplikację? ⚙️ → „🧪 Pokaż komuś aplikację” → 📤 Wyślij link.','Demo ma przykładowe dane, zapyta o imię gościa i nie widzi niczego z Waszego budżetu. Zmiany zostają tylko w jego przeglądarce.','📖 ⚙️ → „Co nowego i jak to działa”: lista wszystkich funkcji – stuknij, a zobaczysz, do czego służą i jak ich używać. Lupa 🔍 też je znajdzie.','Nowe „Pierwsze kroki” z kotkami: ⚙️ → „Pokaż pierwsze kroki”.']},
  {v:17,title:'Wygodniej i ładniej 🎨',scene:'duo',items:['Cztery zakładki: Budżet · Rejestr · Stałe · 💰 Majątek (Oszczędności i Konta razem). Analiza otwiera się z Budżetu.','🔍 w nagłówku szuka wszędzie: wpisy (też po kwocie), pozycje, konta, instrumenty.','Przytrzymaj wpis w Rejestrze: 📋 Duplikuj, ↩️ Zwrot, 🗑️ Usuń. Przesuń palcem w bok, żeby zmienić miesiąc.','„Zapisz” jest zawsze na dole okienka, a „Zapisz i dodaj kolejny” przyspiesza wpisywanie paragonów.','Budżet jest krótszy: puste pozycje chowają się pod „＋ pustych pozycji”, puste kategorie są na dole.','⚙️ → 🎨 Wygląd: kolor (Wercia różowy, Mati miętowy) i większy tekst A+ / A++.','Nowe „Pierwsze kroki” z kotkami pokazują wszystko po kolei: ⚙️ → „Pokaż pierwsze kroki”.']},
  {v:16,title:'Inwestycje liczą się same 🏛️',scene:'duo',items:['🏛️ Obligacje EDO, COI, ROS i ROD: każdy rok liczę z inflacji GUS sprzed 2 miesięcy + marża. Przycisk „📅 Oprocentowanie” pokazuje każdy rok i pozwala go poprawić.','Przy nowej obligacji podpowiadam oprocentowanie serii, która jest w sprzedaży w tym miesiącu.','🧺 Fundusze PPK i TFI: wybierasz fundusz z listy i wpisujesz liczbę jednostek, a automat codziennie pobiera wartość jednostki.','📈 Na koniec miesiąca automat sam zapisuje wycenę kont z instrumentami (wpis „(automat)”, można go usunąć w Rejestrze).','📌 Płacisz coś co miesiąc, a nie ma tego w Stałych? Po 3 miesiącach zapytam, czy to dodać.']},
  {v:15,title:'Wygoda na co dzień 🗣️',scene:'wink',items:['„Hej Siri, wydatek” – Siri zapyta o kwotę i notatkę, a okienko otworzy się wypełnione (⚙️ → „Siri i skróty” → Jak to ustawić).','🛡️ Przy zakupie od 300 zł zapytam o gwarancję i przypomnę miesiąc przed jej końcem. Lista gwarancji jest w 📌 Stałe → 🔔 Przyp.','🧾 Wydatek oznaczysz „do ulgi w PIT” (z objaśnieniem ulgi). Zestawienie osobno dla Matiego i Werci jest w 💼 Pensje → Rok.','🕑 Przy każdym wpisie widać, kto go dodał lub zmienił, a w ⚙️ jest lista ostatnich zmian.']},
  {v:14,title:'Maile od automatu 📧',scene:'envelope',items:['💾 W pierwszą niedzielę miesiąca Mati dostaje mailem kopię zapasową (mały plik .json.gz). Wczytasz ją w ⚙️ → „Wczytaj kopię”.','📊 1. dnia miesiąca oboje dostajecie pastelowe podsumowanie poprzedniego miesiąca: plan a wydatki, co przekroczone, ile odłożyliście.','Adresy to te, którymi logujecie się do aplikacji.']},
  {v:13,title:'Prawdziwe powiadomienia 🔔',scene:'bell',items:['W ⚙️ → „🔔 Powiadomienia” włączysz powiadomienia na swoim telefonie: rano ok. 7:30 „Na dziś” (tylko gdy coś czeka), o 20:00 przypomnienie, gdy dziś nic nie wpisano.','Wspólne sprawy przychodzą do Was obojga, osobiste (pasek pensji, IKZE) tylko do właściciela. Z powiadomieniami okienka nie wyskakują już same – dzwonek 🔔 zostaje.','🧹 Strażnik porządku pilnuje duplikatów, wpisów bez pozycji i ujemnych sald. „To nie błąd” ukrywa podpowiedź na stałe.','Pilne sprawy widać w małym pasku na górze Budżetu. Automat sam pilnuje, żeby GitHub go nie wyłączył.']},
  {v:12,title:'Okno „Na dziś” 🔔',scene:'duo',items:['Dzwonek 🔔 u góry zbiera wszystko, co czeka: opłaty, paski pensji, wydatki roczne, auto, pożyczki, obligacje, limity i kopię.','Pierwszy raz każdego dnia okno otworzy się samo – tylko wtedy, gdy coś czeka.','Po 20:00, gdy danego dnia nic nie wpisano, przypomnimy o wydatkach. Wszystko w aplikacji, bez kalendarza.']},
  {v:11,title:'Nowa Analiza 📊',scene:'lupa',items:['Przełącznik „Podstawowa | Pełna” – każdy telefon pamięta swój.','Podsumowanie miesiąca z kotkami: co się zmieściło, co przekroczone, co poza planem.','Mati ↔ Wercia, przepływ pieniędzy (Sankey), majątek i kategorie przez 12 miesięcy.','„Wasza inflacja”: kategorie rok do roku obok inflacji GUS.','W widoku „Rok”: eksport do Excela i 🎁 Money Wrapped – Wasz rok opowiedziany przez Bailey i Ivo.']},
  {v:10,title:'Planowanie 📝',scene:'calc',items:['Budżet podpowiada plan: średnia z 3 miesięcy w pustym polu i przycisk „Wypełnij średnimi”.','🏷️ Projekty: stałe (koty, mieszkanie) liczą się do budżetu, jednorazowe (wyjazd, remont) są osobno. Opcjonalny budżet z paskiem.','🚗 Pojazd: przy paliwie wpisujesz litry i licznik – spalanie, cena litra i koszt kilometra liczą się same.','📌 Stałe → „🔔 Przyp.”: OC, przegląd, opony, serwis co X km, szczepienia kotów.','Analiza pokazuje, gdzie wydaliście nietypowo dużo, a Oszczędności – kaskadę nadwyżek do odłożenia.']},
  {v:9,title:'Zobowiązania i należności 🔻🔺',scene:'lupa',items:['W 👛 Konta są teraz zakładki „🔻 My winni” i „🔺 Nam winni”.','Kredyty, raty i pożyczki: od kogo, kto spłaca, warunki, pasek spłaty i szacowany koniec. Przy kredycie w banku wpisujesz „pozostało”, prywatna pożyczka liczy się sama.','Rata to dalej wydatek w Budżecie – w okienku wybierasz tylko, które zobowiązanie spłaca.','Pożyczki dla innych z terminem zwrotu i częściowymi zwrotami. Stare „Udzielone pożyczki” przeniesiesz jednym przyciskiem.']},
  {v:8,title:'Oszczędności i inwestycje 📈',scene:'coin',items:['„🐷 Odłóż” w Oszczędnościach i stałe przelewy na oszczędności w 📌 Stałe.','„📊 Instrumenty” przy kontach inwestycyjnych: ETF, akcje, obligacje (EDO, COI, TOS…), złoto, krypto, lokaty – zysk z ceny i z kursu, kwota na rękę po Belce, termin wykupu.','„📈 Aktualizuj wartości” – wszystkie konta inwestycyjne na jednym ekranie.','Limity IKE, IKZE i OKI, wykres „wpłacone a wartość”, FIRE i poduszka.','📌 Stałe → „📅 Roczne”: wydatki raz w roku z kopertami na wspólnym subkoncie – aplikacja liczy, ile odkładać co miesiąc.']},
  {v:7,title:'Pensje 💼',scene:'papers',items:['W 📌 Stałe → „💼 Pensje” dodasz źródła dochodu Matiego i Werci: umowę o pracę, zlecenie, dzieło albo kontrakt / JDG.','Co miesiąc wpisujesz pasek: składniki, ZUS, zdrowotną, podatek, PPK i potrącenia. „Podpowiedz z brutto” liczy szacunek, a aplikacja sprawdza, czy rachunek się zgadza.','Netto, potrącenia (np. Multisport) i PPK same trafiają do budżetu. ZUS i podatek widać tylko w pasku.','Widok „Rok” podsumowuje wszystko do sprawdzenia PIT-11.']},
  {v:6,title:'Waluty 🌍',scene:'happy',items:['Każde konto może mieć swoją walutę (⚙️ → Konta → Edytuj → Waluta) – euro, dolar, funt i każda inna z tabeli NBP. Kwoty nie są przeliczane na złote.','Wymiana walut to przelew z dwiema kwotami – kurs policzę sam i dopiszę do notatki.','Płacisz kartą złotówkową za granicą? Wpisz kwotę w zł, stuknij „🌍 Płatność w obcej walucie” i podaj kwotę w walucie.','W budżecie zobaczysz np. „wydano 820 zł + 45 €” – plan zostaje w złotych.']},
  {v:5,title:'Drobne 🪙',scene:'coin',items:['W ⚙️ → „🪙 Drobne” ustawisz regułę: z którego konta, na które, zaokrąglenie do 5 albo 10 zł i mnożnik.','Przy wydatku z tego konta pojawi się złota moneta z kwotą drobnych. Odznacz ją, gdy bank ich nie liczy (np. BLIK).','Drobne widać pod wydatkiem w Rejestrze i w Oszczędnościach.']},
  {v:4,title:'Poznajcie nas! 🐾',scene:'happy',items:['Bailey i Ivo zamieszkali w aplikacji – witają na Budżecie i podpowiadają, co warto zrobić.','Pamiętamy o urodzinach, świętach i Dniu Kota.','W ⚙️ → „Bailey i Ivo” ustawisz, ile nas ma być: dużo, mało albo wcale.']},
];
/* 📖 guide to every feature (⚙️ → „Co nowego i jak to działa”): sections → items {i:icon, t:title, s:short, w:what it is for, h:[how, step by step], v?:version it came with} */
export const HELP=[
 {s:'✍️ Wpisywanie',items:[
  {i:'➕',t:'Dodawanie wydatku lub przychodu',s:'kwadratowy ＋ w prawym dolnym rogu',w:'Każdy wydatek, przychód albo przelew między kontami wpisujesz w jednym okienku. Z tych wpisów liczy się cały budżet, salda kont i Analiza.',h:['Stuknij ＋.','Wybierz u góry: Wydatek, Przychód albo Przelew.','Wpisz kwotę (przyciskami + i − dodasz lub odejmiesz kolejne kwoty, np. dwa paragony).','Stuknij „Pozycja budżetu” i wybierz ją z listy albo wpisz kilka liter. Po notatce (np. „Biedronka”) podpowiem pozycję sam.','Sprawdź konto i datę, potem „Zapisz”.']},
  {i:'✍️',t:'Podpowiedzi notatki',s:'najczęstsze sklepy',w:'Gdy stukasz w notatkę albo zaczynasz pisać, pod polem pojawiają się Wasze najczęstsze notatki z ostatniego roku (np. Biedronka, Orlen). Stuknięcie wpisuje nazwę i podpowiada pozycję budżetu.',h:['Okienko wpisu → stuknij „Notatka” albo wpisz pierwsze litery → stuknij podpowiedź.'],v:26},
  {i:'⏩',t:'Zapisz i dodaj kolejny',s:'kilka paragonów pod rząd',w:'Gdy wpisujesz kilka rzeczy naraz, nie musisz za każdym razem otwierać okienka od nowa.',h:['W okienku na dole jest przycisk „Zapisz i dodaj kolejny ›”.','Po zapisaniu okienko otworzy się puste, z tym samym kontem i datą.'],v:17},
  {i:'👯',t:'Podwójny wpis',s:'ten sam paragon dwa razy',w:'Gdy zapisujesz wpis z tą samą kwotą, w tym samym lub sąsiednim dniu i z tą samą notatką albo pozycją co istniejący, aplikacja pyta, czy to nie ten sam zakup (np. gdy oboje wpisaliście jeden paragon).',h:['„Nie zapisuj” – okienko zostaje, nic się nie zapisuje.','„Zapisz mimo to” – gdy to naprawdę drugi taki sam zakup.'],v:28},
  {i:'🚫',t:'Bez minusa na koncie',s:'wpis, na który konta nie stać, się nie zapisze',w:'Na prawdziwym koncie nie może być minusa, więc aplikacja nie zapisze wydatku ani przelewu, po którym saldo konta spadłoby poniżej zera – ani w dniu wpisu, ani w żadnym dniu później. Sprawdzane są konta bieżące, subkonta i oszczędności (inwestycje nie – ich wartość zmienia się z kursami).',h:['Gdy pojawi się „🙀 Za mało na koncie”, przeanalizuj konta: może brakuje wpisanego wpływu (pensji, przelewu), wybrane jest nie to konto albo saldo w aplikacji różni się od banku.','Najpierw wpisz brakujący wpływ, a potem wydatek – albo popraw saldo w 💰 Majątek → 👛 Konta → „⚖️ Wyrównaj wszystkie salda naraz” (wyrównanie zawsze się zapisze).','To samo działa przy odhaczaniu opłat i stałych przelewów, zapłacie wydatku rocznego, spłacie długu i pożyczce dla kogoś. 🪙 Drobne bez pieniędzy na koncie po prostu się nie odłożą.','Pieniądze mogą też zniknąć „od drugiej strony”: zmniejszenie albo usunięcie wpływu (przelewu na konto, zwrotu, przychodu spoza paska), przesunięcie go na późniejszy dzień, odznaczenie przychodu stałego i „↩️ Przywróć” / „Cofnij” wydatku są sprawdzane tak samo. Paski pensji, wyrównanie sald i zamknięcie konta zapisują się zawsze.'],v:53},
  {i:'✂️',t:'Dzielenie paragonu',s:'jeden paragon – kilka pozycji',w:'Jeden paragon z Biedronki może zawierać jedzenie, chemię i karmę dla kotów. Każda część trafi do swojej pozycji budżetu.',h:['W okienku stuknij „✂️ Podziel paragon na kilka pozycji”.','Dodaj wiersze z kwotą i pozycją. Reszta kwoty zostaje w pierwszej pozycji.']},
  {i:'↩️',t:'Zwrot',s:'oddali pieniądze za zakup',w:'Zwrot zmniejsza wydatek w tej samej pozycji (nie liczy się jako przychód), więc budżet pokazuje prawdę.',h:['Otwórz wydatek w Rejestrze i stuknij „↩️ Oznacz zwrot” (albo przytrzymaj wpis → Zwrot).','Wpisz, ile wróciło, i datę.']},
  {i:'🌍',t:'Obce waluty',s:'płatność kartą za granicą, konta walutowe',w:'Konto może być w euro czy dolarach – kwoty nigdy się nie przeliczają same. Płacąc kartą złotówkową za granicą, zapiszesz też kwotę w walucie i kurs.',h:['Przy wydatku stuknij „🌍 Płatność w obcej walucie” i wpisz kwotę w walucie.','Przelew między kontami w różnych walutach zapyta, ile wpłynęło na drugie konto.']},
  {i:'🪙',t:'Drobne',s:'zaokrąglanie jak w Revolucie',w:'Każdy wydatek z konta z regułą zaokrągla się w górę, a różnica idzie na oszczędności. Małe kwoty, a po roku robi się z tego sporo.',h:['⚙️ → 🗂️ Kategorie i drobne → „+ Reguła”: wybierz konto, na które idą drobne, i krok (5 lub 10 zł).','Przy wydatku z tego konta widać złotą monetę – stuknij ją, jeśli tym razem nie chcesz odkładać.']},
  {i:'📷',t:'Zdjęcie paragonu',s:'paragon, gwarancja, faktura',w:'Do wpisu możesz dołączyć do 3 zdjęć (paragon, karta gwarancyjna, faktura). Telefon sam je zmniejsza, więc mieszczą się w darmowym miejscu Firebase. Zdjęcie wczytuje się dopiero, gdy otworzysz wpis.',h:['Okienko wpisu → na dole „📷 Zdjęcie paragonu” → aparat albo galeria.','Stuknij miniaturkę – powiększenie i „💾 Zapisz w telefonie”; × usuwa zdjęcie (po „Zapisz”).','⚙️ → 🛡️ Bezpieczeństwo → „📷 Pobierz kopię ze zdjęciami” – raz na jakiś czas, bo mail z kopią nie zawiera zdjęć.'],v:25},
  {i:'🛡️',t:'Gwarancja',s:'przypomnienie przed końcem gwarancji',w:'Przy droższym zakupie (od 300 zł) zapisujesz, jak długo trwa gwarancja. Miesiąc przed końcem przypomnę – to ostatni moment na reklamację.',h:['W okienku wydatku od 300 zł pojawi się „🛡️ Gwarancja” – wybierz 1, 2, 3, 5 lat albo datę.','Lista wszystkich gwarancji: 📌 Stałe → 📅 Roczne i terminy (na dole).'],v:15},
  {i:'🤝',t:'Za kogoś',s:'zakup, który ktoś Wam odda – poza budżetem',w:'Płacisz za coś dla kogoś (np. taśmy dla taty), a on zaraz odda pieniądze. Wpis zmniejsza saldo konta i normalnie odkłada 🪙 drobne, ale nie liczy się do budżetu, planu ani Analizy. Zwrot też nie jest przychodem – zamyka sprawę.',h:['W okienku wydatku stuknij „🤝 Za kogoś” i wpisz, kto odda (imiona podpowiadają się same). W Rejestrze widać „🤝 za: Tata (poza budżetem)”.','Gdy odda: 👛 Konta → 🔺 Nam winni → „✓ Oddał” – kwota, konto i dzień. Przy częściowym zwrocie reszta czeka dalej.','Oddał więcej (np. 200 zł za 150 zł)? Aplikacja zapyta o nadwyżkę: 🎁 prezent – przychód w budżecie (domyślnie) albo 🤝 też do oddania – trafi do 🔻 My winni. Wybór zapamiętuje jako domyślny.','„Nie odda – wlicz do budżetu”: zakup wraca do budżetu jako zwykły wydatek, a to, co już oddał, zmniejsza go jak zwrot w sklepie.','Po 14 dniach bez zwrotu przypomni 🔔 „Na dziś”.'],v:77},
  {i:'🧾',t:'Ulga w PIT',s:'wydatki do zeznania podatkowego',w:'Oznaczasz wydatki, które mogą obniżyć podatek (internet, darowizny, rehabilitacja, termomodernizacja). W styczniu masz gotowe zestawienie – osobno dla każdego z Was. To podpowiedź, nie porada podatkowa.',h:['W okienku wydatku stuknij „🧾 Do ulgi w PIT” i wybierz ulgę (pod spodem krótkie objaśnienie).','Zestawienie: 📌 Stałe → 💼 Pensje → Rok → „Pomocnik PIT”.'],v:15},
  {i:'🗣️',t:'Siri i skróty',s:'„Hej Siri, wydatek”',w:'Siri pyta o kwotę i notatkę, a aplikacja otwiera się z gotowym okienkiem – zostaje tylko „Zapisz”.',h:['⚙️ → 🤖 Automaty → 🗣️ Siri i skróty → „Jak to ustawić” i krok po kroku utwórz skrót w aplikacji Skróty.','Na Androidzie i Macu przytrzymanie ikony aplikacji pokazuje też skróty (Nowy wydatek, Na dziś) – iPhone tego nie umie, tam służy do tego „📲 Przycisk na ekranie”.','📲 Przycisk „Dodaj wydatek” na ekranie głównym albo blokady: ⚙️ → 🤖 Automaty → 🗣️ Siri i skróty → „📲 Przycisk na ekranie” – skrót w aplikacji Skróty i widżet Skrótów, jedno stuknięcie otwiera nowy wydatek.'],v:73}]},
 {s:'📊 Budżet i Analiza',items:[
  {i:'👥',t:'Kto płaci i czy starczy',s:'budżet każdego z Was i wspólnych kont',w:'Aplikacja liczy osobno Matiego, Wercię i wspólne konta: ile jest teraz na kontach i subkontach, ile jeszcze wpłynie i ile jeszcze wyjdzie według planu – i ile zostanie na koniec miesiąca (prawdziwe kwoty, bez odejmowania zapasu): ✅ powyżej 300 zł, 🟡 na styk, ⚠️ poniżej zera. Pokazuje też dzień, w którym będzie najmniej (np. tuż przed wypłatą). Wlicza przelewy na wspólne, do drugiej osoby i na oszczędności.',h:['W Budżecie przy pozycji wydatków stuknij przycisk „Płaci” (z „?” = podpowiedź z ostatnich 3 miesięcy).','Wybierz: Mati, Wercia, Wspólne, Po połowie albo Inaczej (suwak podziału).','Zostaw „Na stałe” albo wybierz „Tylko …” dla jednego miesiąca, potem „Zapisz”. „↺ wróć do podpowiedzi” usuwa ustawienie.','Opłaty stałe liczą się same temu, z czyjego konta schodzą – „Płaci” dotyczy reszty planu.','Na dole Budżetu zwinięta zakładka „👥 Czy starczy?” – jedno zdanie (✅ wszystkim starczy, 🟡 na styk albo ⚠️ komu zabraknie). Stuknij ją, żeby rozwinąć, a potem stuknij osobę: na kontach teraz, jeszcze wpłynie, jeszcze wyjdzie i „najmniej”.','Z planu liczy się tylko to, czego dana osoba jeszcze nie wydała ze swoich kont.','Po rozwinięciu: „Część planu” – ile już wydane z części tej osoby, ▲ pozycje ponad nią; 💡 podpowiedzi: zapłacone ze swojego konta za wspólne (można sobie oddać) i ile dołożyć po połowie, gdy wspólnym brakuje.'],v:57},
  {i:'📊',t:'Plan i paski',s:'ile zostało w każdej pozycji',w:'Na każdą pozycję wpisujesz plan na miesiąc. Paski pokazują, ile już wydaliście i ile zostało. Wydatek bez planu jest „poza planem”.',h:['W Budżecie stuknij kategorię, żeby ją rozwinąć.','Wpisz kwotę w polu „Plan” przy pozycji.','🔎 Stuknij nazwę pozycji (ze strzałką ›) – zobaczysz jej wpisy z miesiąca; stąd też „＋ Dodaj” do tej pozycji i „W Rejestrze”.','„Skopiuj plan z poprzedniego miesiąca” (na dole, gdy miesiąc nie ma jeszcze planu) oszczędza pisanie, a „Wypełnij średnimi” podpowiada kwoty z ostatnich miesięcy.'],v:49},
  {i:'📅',t:'Wydatki roczne w planie',s:'OC, prezenty – same w planie miesiąca',w:'Gdy w danym miesiącu przypada wydatek roczny, jego kwota sama dolicza się do planu jego pozycji. Dzięki temu np. OC w marcu nie jest „poza planem”, a w kwietniu plan nie jest za duży (ta kwota się nie kopiuje). Zapłacony wcześniej – liczy się w miesiącu zapłaty.',h:['Wystarczy dodać wydatek w 📌 Stałe → 📅 Roczne (kwota, miesiąc, pozycja budżetu).','W Budżecie pod pozycją widać „📅 do planu doliczone: …”. Pole planu pokazuje tylko to, co wpisaliście sami.'],v:31},
  {i:'🗓️',t:'Zamknięcie miesiąca',s:'5 kroków dzień przed wypłatą – każde z Was osobno',w:'Raz w miesiącu warto sprawdzić, czy liczby w aplikacji są prawdziwe, i przygotować kolejny miesiąc. Każde z Was zamyka miesiąc samo, dzień przed swoją najwcześniejszą wypłatą – wtedy na koncie jest to, co naprawdę zostało z poprzedniej pensji. Kroki: 1) salda Twoich i wspólnych kont z bankiem, 2) co było ponad plan (wspólny), 3) nadwyżka na Twoich kontach bieżących (kaskada), 4) plan na nowy miesiąc (wspólny), 5) Twoje i wspólne cele.',h:['🌊 Krok 3 (kaskada): dzień przed wypłatą liczę nadwyżkę na Twoich kontach bieżących – saldo minus zapas (domyślnie 250 zł) i nieodhaczone rachunki do wypłaty – i proponuję przelew na oszczędności (do limitu IKE/IKZE). Wcześniej pokażę tylko, od kiedy ją policzę.','Dzień wypłaty aplikacja zna sama z pasków z ostatnich 3 miesięcy: rozpozna „koniec miesiąca”, a gdy dzień wypada w weekend – piątek przed nim. Bez pasków bierze dzień ze źródła dochodu, a bez źródła dochodu – od 1. dnia miesiąca.','W 🔔 „Na dziś” przez ok. 10 dni (zawsze też przycisk „🗓️ Zamknięcie miesiąca” na dole Budżetu), rano w dniu startu powiadomienie (tylko do Ciebie). Wypłata od 20. dnia → zamykasz bieżący miesiąc, wcześniej – poprzedni.','„Co było ponad plan” i „Plan” są wspólne – odhaczone przez jedno z Was są odhaczone u obojga. Przy planie podpowiadam średnią z 3 miesięcy (jeden drogi miesiąc nie podnosi planu na stałe).','Salda: „✓ Zgadza się” przy koncie albo „⚖️ Wyrównaj wszystkie salda naraz”. W każdej chwili: przycisk „🗓️ Zamknięcie miesiąca” na dole Budżetu.'],v:37},
  {i:'📊',t:'Plan a rzeczywistość',s:'czy plan pasuje do wydatków',w:'Po kilku miesiącach widać, które pozycje regularnie przekraczają plan (plan jest za mały albo wydatki za duże), a które są dużo poniżej. Jednym stuknięciem poprawisz plan od następnego miesiąca – wcześniejsze miesiące zostają bez zmian.',h:['📈 Analiza → Rok → karta „Plan a rzeczywistość”.','„Ustaw … od listopada” zmienia plan tej pozycji od następnego miesiąca.'],v:31},
  {i:'🙈',t:'Ukrywanie pozycji i kategorii',s:'np. spłacona pożyczka, kategoria na później',w:'Ukryta pozycja nie pokazuje się w Budżecie ani przy wpisywaniu, ale jej historia zostaje w Rejestrze i Analizie. Gdy w danym miesiącu ma jakiś wpis, Budżet i tak ją pokaże, żeby sumy się zgadzały. Pozycji z wpisami nie da się usunąć – tylko ukryć; pustą możesz usunąć.',h:['⚙️ → 🗂️ Kategorie i drobne → stuknij pozycję → „🙈 Ukryj”.','Całą kategorię: stuknij jej nazwę → „Widoczność: Ukryta”.','Przywracanie: pod kategorią „🙈 Ukryte: … ↺ przywróć”.'],v:31},
  {i:'🔽',t:'Krótszy Budżet',s:'puste pozycje schowane',w:'Pozycje bez planu i bez wydatków nie zajmują miejsca, a kategorie zupełnie puste są w jednej linijce na dole.',h:['W kategorii stuknij „＋ N pustych pozycji”, żeby je pokazać (np. żeby wpisać plan).','Puste kategorie na dole – stuknij nazwę, żeby ją otworzyć.','Filtr „Bez planu” zawsze pokazuje wszystkie pozycje bez planu.'],v:17},
  {i:'👆',t:'Zmiana miesiąca palcem',s:'przesuń w lewo albo w prawo',w:'Zamiast strzałek ‹ › w nagłówku możesz przesunąć palcem po ekranie.',h:['Przesuń w lewo – następny miesiąc, w prawo – poprzedni. Działa w Budżecie, Rejestrze, Stałych i Analizie.'],v:17},
  {i:'📈',t:'Analiza',s:'wykresy, podsumowanie, Mati ↔ Wercia',w:'Podsumowanie miesiąca lub roku: na co idą pieniądze, porównanie z poprzednim okresem, kto ile wydaje, majątek w czasie, inflacja osobista, „Money Wrapped”.',h:['W Budżecie stuknij przycisk „📈 Analiza”.','Przełącz Miesiąc / Rok. „Podstawowa” pokazuje najważniejsze, „Pełna” – wszystkie wykresy.','Eksport do pliku CSV jest na dole.']},
  {i:'⏳',t:'Trwający miesiąc w Analizie',s:'porównanie do tego samego dnia',w:'Gdy miesiąc jeszcze trwa, porównuję go z poprzednim miesiącem do tego samego dnia – inaczej 10. dnia wszystko wyglądałoby na „dużo mniej niż ostatnio”. Ocenę „zmieściło się” i „wyraźnie mniej niż plan” pokazuję po końcu miesiąca.',h:['📈 Analiza → Miesiąc: pod kafelkami „⏳ Miesiąc jeszcze trwa – strzałki porównują z … do N. dnia”.'],v:35},
  {i:'📅',t:'Rok temu',s:'ten sam miesiąc rok wcześniej',w:'W Analizie → Miesiąc (Podstawowa i Pełna) karta porównuje przychody, wydatki i odłożone z tym samym miesiącem rok wcześniej i pokazuje 3 kategorie, które zmieniły się najbardziej (np. prezenty w grudniu, ogrzewanie zimą). W trwającym miesiącu porównuje do tego samego dnia. Pokazuje się, gdy są wpisy sprzed roku.',h:['📈 Analiza → Miesiąc → karta „📅 Rok temu”.'],v:48},
  {i:'🏪',t:'Gdzie wydajemy',s:'sklepy i miejsca z notatek',w:'Zestawienie miejsc z notatek wydatków (Biedronka, Lidl, Glovo…): ile wydaliście, ile razy i średnio za jednym razem. Bez opłat stałych.',h:['📈 Analiza → Pełna → „🏪 Gdzie wydajemy” (w miesiącu i w roku).','Im staranniej wpisujecie notatkę (ta sama nazwa sklepu), tym lepsze zestawienie.'],v:24},
  {i:'🖨️',t:'Podsumowanie roku',s:'jedna strona do PDF i mail 1 stycznia',w:'Cały rok na jednej stronie: przychody i wydatki, miesiąc po miesiącu, na co poszło najwięcej, ile odłożyliście, majątek na początku i na końcu roku, Mati ↔ Wercia, IKE/IKZE/PPK i ulgi do PIT.',h:['📈 Analiza → przełącz na „Rok” → „🖨️ Podsumowanie roku”.','„Zapisz jako PDF / drukuj” otwiera okno drukowania – na telefonie wybierz „Zapisz jako PDF” albo udostępnij.','1 stycznia automat wysyła podsumowanie poprzedniego roku mailem do Was obojga.'],v:19},
  {i:'🏷️',t:'Projekty',s:'auto, koty, wakacje – ile kosztują',w:'Projekt zbiera wydatki z różnych pozycji, np. wszystko o samochodzie albo o wakacjach. Przy aucie liczy też spalanie z tankowań.',h:['Na dole Budżetu: „🏷️ Projekty” → „+ Projekt”.','Przy wydatku wybierz projekt w okienku.']}]},
 {s:'🧾 Rejestr i szukanie',items:[
  {i:'🧾',t:'Rejestr',s:'wszystkie wpisy z filtrami',w:'Lista wszystkich wpisów miesiąca, roku albo całości – każdy w dwóch linijkach: pozycja, a pod nią notatka · konto · osoba. Kategorię widać po kolorowej ikonce, przy każdym dniu suma wydatków.',h:['Wyszukiwarka u góry szuka po notatce, pozycji, koncie i kwocie – np. „>200” albo „100-300”.','Obok okresu (Ten miesiąc / Cały rok / Wszystko) jest „⚙️ Filtry”: rodzaj, osoba, konto, kategoria. Liczba w nawiasie mówi, ile filtrów działa. „✕ Wyczyść filtry” wraca do wszystkiego.'],v:35},
  {i:'✋',t:'Przytrzymanie wpisu',s:'Duplikuj, Zwrot, Usuń',w:'Szybkie akcje bez otwierania wpisu.',h:['Przytrzymaj wpis w Rejestrze palcem przez pół sekundy.','📋 Duplikuj – to samo jeszcze raz (np. ta sama kawa), z dzisiejszą datą do zmiany.','↩️ Zwrot, ✏️ Otwórz, 🗑️ Usuń (z „Cofnij” w dymku).'],v:17},
  {i:'🔍',t:'Szukaj wszędzie',s:'lupa w nagłówku',w:'Jedno wyszukiwanie po wpisach, pozycjach budżetu, kontach, instrumentach i opłatach stałych.',h:['Stuknij 🔍 na górze i wpisz kilka liter albo kwotę.','Stuknij wynik – przeniosę Cię we właściwe miejsce.'],v:17},
  {i:'🗑️',t:'Ostatnio usunięte',s:'przywróć usunięty wpis',w:'Usunięty wpis nie znika na zawsze. Przez 60 dni widać go na liście i można go jednym stuknięciem wstawić z powrotem – razem z jego zwrotami, PPK i odsetkami.',h:['⚙️ → 🛡️ Bezpieczeństwo → „🗑️ Ostatnio usunięte” → „↩️ Przywróć”.','Po przywróceniu przez chwilę jest jeszcze „Cofnij”.','🎯 Tak samo wraca usunięty cel (koperta) – też jest na tej liście.'],v:23},
  {i:'🕑',t:'Kto co zmienił',s:'dodał, zmienił, usunął',w:'Przy każdym wpisie widać, kto go dodał i kto zmienił – przydaje się, gdy oboje wpisujecie.',h:['Otwórz wpis – na dole okienka jest „dodał / zmieniła”.','Lista ostatnich zmian: ⚙️ → 🛡️ Bezpieczeństwo → „🕑 Ostatnie zmiany”.'],v:15},
  {i:'🧹',t:'Strażnik porządku',s:'duplikaty, brak pozycji, ujemne saldo',w:'Sam wyłapuje możliwe pomyłki: podwójne wpisy, wpisy bez pozycji, ujemne saldo konta (bieżącego, subkonta albo oszczędności – pilnie, codziennie), pasek pensji, który się nie zgadza, wpis zapisany dwa razy, pensję z paska policzoną podwójnie, wydatek „co 2 lata” bez pierwszego terminu, a także opłaty, pensje i reguły drobnych ustawione na konto, którego już nie ma.',h:['Podpowiedzi są w 🔔 „Na dziś”.','„To nie błąd” ukrywa daną podpowiedź na stałe.'],v:69}]},
 {s:'📌 Stałe',items:[
  {i:'📌',t:'Opłaty i przychody stałe',s:'odhaczasz co miesiąc',w:'Czynsz, prąd, abonamenty i stałe przychody (np. najem) wpisujesz raz. Co miesiąc odhaczasz je jednym stuknięciem, a wpis sam trafia do Rejestru. O terminach przypominam w 🔔 „Na dziś” i powiadomieniem.',h:['📌 Stałe → „+ Opłata” albo „📥 + Przychód stały”.','Stuknij kwadracik, gdy zapłacone. Drugie stuknięcie zapyta, czy usunąć wpis – „Nie” zostawia wszystko bez zmian.','Przy najmie wybierz „🏠 Najem” – przypomnę o ryczałcie.','Kolejność: opłaty stałe, koszt w roku, stałe przelewy, a na dole przychody stałe (bez nich – tylko mały przycisk „+ Przychód stały”).'],v:50},
  {i:'🔁',t:'Stałe przelewy',s:'oszczędności, zrzutka na wspólne',w:'Przelew co miesiąc z konta na konto: na oszczędności, na konto wspólne, na konto drugiej osoby albo na subkonto. Odhaczasz go jak opłatę. Jako „odłożone” liczą się tylko przelewy na oszczędności i inwestycje.',h:['📌 Stałe → „🔁 Stałe przelewy” → „+ Przelew”.','Gdy ten sam przelew (te same konta, podobna kwota) jest co miesiąc od 3 miesięcy, zapytam „Dodać do stałych przelewów?”.'],v:37},
  {i:'⚠️',t:'Nie starczy na rachunki',s:'ostrzeżenie przed terminem opłaty',w:'Sprawdzam każde konto bieżące do końca miesiąca: odejmuję nieodhaczone opłaty stałe, stałe przelewy i raty z 📌 Stałe, doliczam to, co wpłynie wcześniej (pensję – kwotą z ostatniego paska, przychody stałe, stałe przelewy na to konto). Gdy na którąś opłatę zabraknie – ostrzeżenie w 🔔 „Na dziś”. Liczę tylko rzeczy stałe, nie zakupy.',h:['„Przelej” otwiera przelew na to konto z brakującą kwotą. „Wiem” chowa ostrzeżenie na ten miesiąc.','Powiadomienie: pierwszego dnia problemu i dzień przed opłatą – do właściciela konta, przy koncie wspólnym do obojga.'],v:37},
  {i:'🔗',t:'Jeden rachunek – jeden wpis',s:'wpis z ＋ a opłata stała',w:'Opłatę stałą możesz zapłacić na dwa sposoby: odhaczyć w 📌 Stałe albo wpisać przez ＋. Aplikacja pilnuje, żeby ten sam rachunek nie policzył się dwa razy: wpis z ＋ podobny do nieodhaczonej opłaty (ta sama pozycja i podobna kwota albo nazwa w notatce) – pyta, czy go odhaczyć; przy odhaczaniu, gdy taki wpis już jest – proponuje połączenie. Tak samo przy wydatkach rocznych (OC, ubezpieczenie).',h:['Zapisujesz wpis → „To … z opłat stałych?” → „Tak, odhacz”.','📌 Stałe → kwadracik przy opłacie z „💡 jest podobny wpis” → „Połącz z tym wpisem”.','Gdy to naprawdę coś innego: „Nie, to coś innego” albo „To inny – dodaj nowy wpis”.'],v:34},
  {i:'📌',t:'Plan a opłaty stałe',s:'plan nie mniejszy niż rachunki',w:'Jeśli plan pozycji jest niższy niż suma jej opłat stałych (np. czynsz wzrósł, a plan skopiował się ze starego miesiąca), pozycja byłaby co miesiąc „ponad plan”. 🔔 „Na dziś” to pokazuje i jednym przyciskiem podnosi plan.',h:['🔔 Na dziś → „📌 Plan niższy niż opłaty stałe” → „Podnieś plan” (przy planowaniu przyszłego miesiąca – karta na Budżecie).','Pod pozycją widać „📌 opłaty stałe w tej pozycji: …”.'],v:34},
  {i:'📄',t:'Koniec umowy',s:'przypomnienie 2 miesiące wcześniej',w:'Przy opłacie stałej (internet, telefon, ubezpieczenie) wpisz, do kiedy masz umowę. 2 miesiące przed końcem przypomnę w „Na dziś”, żeby porównać oferty albo negocjować cenę.',h:['📌 Stałe → stuknij nazwę opłaty → „📄 Umowa do”.','Na liście opłat widać „📄 umowa do …”. W „Na dziś” przycisk „Załatwione” chowa przypomnienie; przy nowej umowie wpisz nową datę.'],v:24},
  {i:'👥',t:'Opłaty według osoby',s:'Wszystkie · Mati · Wercia · Wspólne',w:'W 📌 Opłatach możesz zobaczyć tylko opłaty, przychody i przelewy stałe jednej osoby. Czyje są, wynika z konta, z którego idą (konto wspólne = wspólne). Gdy jest inaczej – np. telefon Matiego płacony ze wspólnego konta – ustaw w edycji „👥 Dotyczy”.',h:['📌 Stałe → 📌 Opłaty → przełącznik na górze.','Telefon zapamiętuje ostatni wybór.'],v:42},
  {i:'📆',t:'Opłaty stałe w roku',s:'ile kosztują rocznie',w:'Pod listą opłat stałych: ile kosztują w roku i miesięcznie, w tym subskrypcje (z nazwami) i wydatki roczne.',h:['📌 Stałe → „📆 Opłaty stałe w roku”.'],v:24},
  {i:'📋',t:'Przegląd subskrypcji',s:'raz w roku: czy wszystkich używacie?',w:'Raz w roku w „Na dziś” każde z Was dostaje listę swoich i wspólnych subskrypcji (opłaty stałe w kategorii subskrypcji, abonamentów, aplikacji) z kosztem miesięcznym i rocznym. „Rezygnuję” usuwa ją z 📌 Stałe – dawne płatności zostają w Rejestrze. Po „Gotowe – przejrzane” przypomnę za rok.',h:['🔔 Na dziś → „📋 Przegląd subskrypcji” → „Przejrzyj”.','W każdej chwili: 📌 Stałe → „📆 Opłaty stałe w roku” → „📋 Przejrzyj”.','„✓ Zostaje” tylko zaznacza, „✎ Zmień” otwiera opłatę (np. nowa cena), „✕ Rezygnuję” – po pytaniu usuwa ją z opłat stałych. Pamiętajcie wyłączyć ją też w samym serwisie.'],v:48},
  {i:'💡',t:'Podpowiedź stałej opłaty',s:'„Dodać do opłat stałych?”',w:'Gdy coś płacisz co miesiąc (ta sama notatka, podobna kwota, 3 miesiące z rzędu), a nie ma tego w Stałych – zapytam, czy to dodać.',h:['Podpowiedź pojawi się w 🔔 „Na dziś”.','„Dodaj” otwiera gotowy formularz, „Nie, dzięki” – więcej nie zapytam.'],v:16},
  {i:'🧮',t:'Pasek z kwoty netto',s:'gdy nie masz jeszcze paska',w:'Wystarczy kwota, która wpłynęła na konto. Aplikacja policzy orientacyjnie brutto, ZUS, zdrowotną, podatek i PPK – tak, żeby rachunek paska się zgadzał. Gdy dostaniesz prawdziwy pasek, przepiszesz z niego brutto.',h:['📌 Stałe → 💼 Pensje → „+ Wpisz pasek” → „🧮 Podpowiedz z netto”.','Wpisz kwotę z aplikacji banku; przy PPK wybierz, czy było w tej wypłacie.','Potrącenia (np. Multisport) doliczę – są w pasku w „Potrącenia”.','„✓ To już kwoty z paska” zdejmuje oznaczenie szacunku.'],v:29},
  {i:'🎓',t:'Ulga dla młodych',s:'do 26 lat bez podatku od pensji',w:'Do dnia 26. urodzin pensja z umowy o pracę i umowy zlecenia (razem z wpłatą PPK pracodawcy) jest zwolniona z podatku – do 85 528 zł w roku, ze wszystkich umów razem. ZUS i składka zdrowotna są jak zwykle. Aplikacja liczy to sama z daty urodzenia: w pasku widać, ile jest bez podatku i ile limitu zostało. Miesiąc przed 26. urodzinami przypomnę, że kolejne wypłaty będą niższe.',h:['Data urodzenia: Bailey i Ivo pytają o nią przy starcie, zmienisz ją w ⚙️ → „Kto korzysta z tego telefonu?”.','💼 Pensje → pasek → „Podpowiedz z brutto” albo „z netto” – podatek policzy się z ulgą.','💼 Pensje → Rok: „w tym zwolniony (ulga dla młodych)” do porównania z PIT-11.'],v:33},
  {i:'✂️',t:'Potrącenia z pensji',s:'ubezpieczenie grupowe, Multisport',w:'To, co pracodawca potrąca od razu z wypłaty, nie wpływa na konto, ale jest Waszym wydatkiem. Wpisujesz to raz przy źródle dochodu – w każdym nowym pasku pojawi się samo i trafi do budżetu w wybranej pozycji.',h:['💼 Pensje → „+ Źródło dochodu” (albo ⋯ przy źródle) → trzecie okienko „✂️ Potrącenia z pensji”.','Zmiana kwoty w danym miesiącu: w pasku, w „Potrącenia”. Kolejny pasek weźmie kwoty z poprzedniego.'],v:29},
  {i:'➕',t:'Inne przychody',s:'sprzedaż rzeczy, premia, zwrot PIT, najem',w:'Przychody spoza pasków wpisujesz jak zwykły przychód. W 💼 Pensje widać je wszystkie pod pensjami, razem z sumą miesiąca. Stały przychód (np. najem) dodasz w 📌 Stałe → „+ Przychód” i będziesz go odhaczać co miesiąc.',h:['💼 Pensje → „+ Inny przychód” (albo ＋ → Przychód).','Najem: 📌 Stałe → Opłaty → „+ Przychód”.'],v:29},
  {i:'🏠',t:'Najem i ryczałt',s:'przypomnienie o podatku od najmu',w:'Przy przychodzie stałym z najmu przypomnę o ryczałcie (8,5% przychodu, do 100 000 zł rocznie) – do 20. dnia po miesiącu albo po kwartale – z wyliczoną kwotą, a w marcu i kwietniu o PIT-28 (termin 30 kwietnia).',h:['📌 Stałe → „+ Przychód” (albo stuknij istniejący) → „🏠 Najem – przypominać o ryczałcie?” → co miesiąc albo co kwartał.','W „Na dziś” stuknij „✓ Zapłacone”, gdy podatek pójdzie.'],v:50},
  {i:'🧾',t:'PIT co roku',s:'od 1 marca do 30 kwietnia',w:'Od 1 marca w „Na dziś” przypominam o zeznaniu za poprzedni rok – każdemu z Was osobno – z przyciskiem do zestawienia ulg i IKZE. Powiadomienie przychodzi 1 marca, 1 i 20 kwietnia.',h:['W „Na dziś” stuknij „Zestawienie”, a po złożeniu „✓ Złożone”.'],v:32},
  {i:'💼',t:'Pensje i pasek',s:'brutto, netto, PPK, PIT-11',w:'Źródła dochodu każdego z Was (umowa o pracę, zlecenie, dzieło, JDG). Co miesiąc wpisujesz pasek: przychód w budżecie, wpłaty PPK i potrącenia liczą się same, a widok roku pomaga przy PIT.',h:['📌 Stałe → 💼 Pensje → „+ Źródło dochodu”.','Co miesiąc „Wpisz pasek” – „Skopiuj z poprzedniego miesiąca” albo „Podpowiedz z brutto” przyspieszają.','„Rok” – suma do porównania z PIT-11 i „Pomocnik PIT”.','JDG: w źródle dochodu wybierasz formę podatku i ZUS (ulga na start, preferencyjny, pełny, z chorobowym albo własna kwota) – podpowiedź liczy ZUS, zdrowotną (najniższa, limit odliczenia na liniowym, próg na ryczałcie) i podatek według zasad 2026.','Zlecenie studenta do 26 lat – bez ZUS i zdrowotnej.'],v:66},
  {i:'📅',t:'Roczne i terminy',s:'OC, ubezpieczenie, prezenty – koperty i przypomnienia',w:'Jedno miejsce na wszystko, co wraca co rok albo co kilka miesięcy. Z kwotą – aplikacja liczy, ile odkładać co miesiąc na wspólne subkonto, i dolicza tę kwotę do planu w miesiącu płatności. Bez kwoty – tylko przypomina. Zawsze ok. 2 tygodnie przed terminem (także gdy koperta jest już pełna).',h:['📌 Stałe → 📅 Roczne i terminy → „+ Dodaj” → wybierz gotowe (OC, przegląd, opony, szczepienie kotów…) albo wpisz własne.','Wpisz kwotę, najbliższy termin i co ile się powtarza.','W 🔔 „Na dziś” widać, ile w tym miesiącu jeszcze odłożyć. Po zapłacie stuknij „✓ Zapłacone”.'],v:32},
  {i:'🔔',t:'Terminy bez odkładania',s:'opony, serwis co X km, szczepienie kotów',w:'Rzeczy co jakiś czas, na które nie odkładacie osobno – po dacie albo po kilometrach auta. Przypomnę ok. 2 tygodnie przed terminem.',h:['📌 Stałe → 📅 Roczne i terminy → „+ Dodaj” → wybierz gotowe albo wpisz własne, bez kwoty.','„✓ Zrobione” przesuwa termin na następny raz. W „Edytuj” możesz dopisać kwotę – wtedy będę liczyć odkładanie.'],v:32}]},
 {s:'💰 Majątek',items:[
  {i:'🥧',t:'Z czego składa się majątek',s:'koło: gotówka, obligacje, akcje, złoto…',w:'Karta w Oszczędnościach pokazuje, jak rozłożone są Wasze pieniądze na kontach oszczędnościowych i inwestycyjnych (bez PPK) – według dzisiejszej wyceny. To pierwszy krok doradcy: najpierw widać, jak jest, a widełki planu pod kołem pokazują, jak ma być.',h:['💰 Majątek → 🐷 Oszczędności → karta „🥧 Z czego składa się majątek” (Razem albo osoba).','Stuknij grupę (np. 📈 Akcje), żeby zobaczyć klasy i instrumenty; „‹ Wróć” – z powrotem.','Stuknij instrument albo konto, żeby zmienić klasę. „＋ Własna klasa…” na dole listy dodaje własną.','„❓ Do przypisania” = fundusz, którego nie znam – kotki zapytają, w co inwestuje.'],v:58},
  {i:'🏠',t:'Nieruchomości i inne aktywa',s:'mieszkanie, wynajem, kolekcja – poza kontami',w:'Rzeczy warte pieniądze, które nie są kontami: mieszkanie, kawalerka na wynajem, działka, kolekcja, udziały. Wartość wpisujecie ręcznie (ostrożnie) i odświeżacie co 1–3 lata. Kredyt z 🔻 odejmuje się od wartości. Nie zmieniają sald, budżetu ani „odłożonych”. Mieszkanie, w którym mieszkacie, nie wchodzi do proporcji – nie zarabia.',h:['💰 Majątek → 🐷 Oszczędności → karta „🥧 Z czego składa się majątek” → „🏠 ＋ Nieruchomość” albo „✨ ＋ Inne aktywo”.','Przy wspólnych wpisz udział Matiego w % (jak w akcie notarialnym) – w zakładce każdej osoby liczy się jej część wartości i kredytu.','Zmiana albo nowa wycena: stuknij pozycję na liście (🏠 Nieruchomości albo w grupie aktywów).','W 👛 Kontach wartość jest pokazana obok zobowiązań („po rozliczeniu wszystkiego”).'],v:59},
  {i:'🧭',t:'Doradca: ankieta i plan',s:'poduszka, długi, limity, proporcje z widełkami',w:'Doradca nie zgaduje przyszłości – pilnuje Waszego planu. Z ankiety wylicza proporcje: akcje według horyzontu i tego, jaki spadek zniesiecie (bierze najostrożniejszą granicę), złoto i gotówkę według odpowiedzi, resztę – obligacje skarbowe indeksowane inflacją. Wspólny portfel liczy według ostrożniejszej osoby.',h:['💰 Majątek → 🐷 Oszczędności → karta „🧭 Doradca” → „📝 Zacznij ankietę z kotkami”.','Po ankiecie: „📄 Propozycja planu” → „✓ Zatwierdzam plan” albo „✎ Zmień proporcje”.','Pod kołem „🥧 Z czego składa się majątek” → paski „jest / ma być” i podpowiedź, co dokupić.','Mati: w swoim planie „👀 Pokaż ankietę Werci”, gdy Wercia ma ją wypełnić.'],v:60},
  {i:'💸',t:'Gdzie wpłacić',s:'IKE, IKZE, poduszka, nadpłata – z wyliczeniem',w:'Wpisujesz kwotę, a kotki mówią, gdzie ją wpłacić i dlaczego. Kolejność: dług, poduszka, a potem pokrowce według progu podatkowego: przy 32% i liniowym najpierw IKZE (zwrot podatku), przy 12% najpierw IKE, przy 0% IKZE wcale. Pieniądze potrzebne w 3 lata – tylko bezpiecznie. Nadpłata kredytu według tego, co ustaliliście w ankiecie.',h:['🐷 Oszczędności → karta „🧭 Doradca” → „💸 Chcę zainwestować…”.','Wpisz kwotę, odpowiedz na 5 krótkich pytań i stuknij „🐾 Policz”.','Stuknij wiersz, żeby zobaczyć „dlaczego”. Niżej porównanie IKE / IKZE / zwykły rachunek i „Na pewno nie tu”.'],v:61},
  {i:'🛒',t:'W co i ile jednostek',s:'fundusz, obligacje, transze, zapisana porada',w:'Kwota na część długoterminową idzie najpierw tam, gdzie do planu brakuje najwięcej – tak wyrównujecie proporcje bez sprzedawania. Kotki wybierają fundusz z Waszej listy: ten, który już macie, albo z tej samej rodziny indeksów. Liczba jednostek po cenie z automatu, z kosztem wymiany waluty w XTB. Duże kwoty w akcje – w transzach.',h:['🐷 Oszczędności → 🧭 Doradca → „💸 Chcę zainwestować…” → „🐾 Policz” → karta „🛒 W co”.','„💾 Zapisz poradę” – lista „📋 Zapisane porady” odhacza się sama po wpisaniu zakupu (📊 Instrumenty) albo przelewu na IKE/IKZE.','„🧮 Która obligacja da najwięcej?” – wybierz okres; liczę po podatku i opłacie za wcześniejszy wykup.'],v:62},
  {i:'🎯',t:'Cele doradcy',s:'emerytura, mieszkanie, kryzys, koszty, najem',w:'Liczby do Waszych celów – fakty i ostrożne założenia, bez prognoz. Emerytura: luka między tym, co chcecie mieć na rękę, a ZUS-em. Mieszkanie: wkład, koszty, czas i test raty (30% dochodów z buforem +2,5 pkt). Test kryzysu: ile w złotych w 3 historycznych kryzysach. Koszty: opłaty funduszy rocznie. Najem: rentowność netto. Zakup nieruchomości kotki podsuwają tylko, gdy wszystkie warunki są spełnione.',h:['🐷 Oszczędności → 🧭 Doradca → „🎯 Cele: emerytura, mieszkanie, kryzys, koszty”.','Brakujące dane uzupełnisz w ankiecie (dział „Cele” i „Nieruchomości”); liczby najmu – przycisk „✎ Wpisz liczby”.'],v:63},
  {i:'🌡️',t:'Termometr i przypomnienia',s:'spokojnie / drogo / przecena, reguła na spadki',w:'Termometr pokazuje fakty z danych automatu: spadek akcji świata od szczytu, cenę względem średniej z 3 lat, obligacje na tle inflacji, realną stopę i kurs dolara. Wpływa tylko na dwie rzeczy: przy „drogo” radzi transze dużych zakupów, przy „przecenie” przypomina Waszą regułę i list do siebie. Przypomnienia doradcy są ciche (bez powiadomień) i można je odhaczyć.',h:['🐷 Oszczędności → karta „🧭 Doradca” → na dole „🌡️ Termometr rynku”.','Przypomnienia – w 🔔 „Na dziś”.','Reguła na spadki i list do siebie – ankieta, dział „Trzymanie kursu”.'],v:64},
  {i:'🧪',t:'Piaskownica i lista życzeń',s:'pojedyncze spółki, tematy, krypto – z limitem',w:'Większość pieniędzy w prostym planie, mały kawałek na eksperymenty. Do piaskownicy liczy się wszystko bardzo ryzykowne: pojedyncze spółki, ETF-y tematyczne, krypto, surowce, kolekcje. Limit to procent części długoterminowej z Waszego planu. Analiza pomysłu to fakty i pytania, nie rekomendacja.',h:['🐷 Oszczędności → 🧭 Doradca → „🧪 Piaskownica”.','Wpisz nazwę, kwotę, rodzaj, powód zakupu i warunek sprzedaży → „🐾 Analizuj”.','„⭐ Zapisz na liście życzeń” – z symbolem i ceną docelową automat pilnuje ceny i kotki dadzą znać w 🔔.','Po zakupie: „✓ Kupione” i wpis w 📊 Instrumenty (zwykły rachunek, nie IKE).'],v:65},
  {i:'🔎',t:'Analiza funduszy',s:'kryteria, dublowanie, lista ETF-ów',w:'Fakty, nie prognozy: czy fundusz jest z Irlandii (UCITS), akumulujący, tani (do ok. 0,25% rocznie) i duży. Ostrzega, gdy macie kilka funduszy „cały świat” albo parę z dwóch rodzin indeksów. Lista 7 ETF-ów z XTB ma datę sprawdzenia.',h:['💰 Majątek → 🐷 Oszczędności → Razem → „🔎 Analiza funduszy”.','Nowy fundusz dodajesz jak zawsze: konto → 📊 Instrumenty → + Dodaj instrument. Przy funduszu z listy wystarczy symbol (np. VWCE.DE) – nazwę i walutę uzupełnię.'],v:58},
  {i:'💰',t:'Oprocentowanie konta',s:'odsetki, promocja, podatek Belki',w:'Aplikacja liczy odsetki konta oszczędnościowego dzień po dniu od salda (saldo × stawka ÷ 365) – także przy promocji z limitem kwoty i po zmianie stawki. Odejmuje podatek Belki 19% (bez podatku przy IKE, IKZE i OKI; przy banku zagranicznym – „Rozliczam sam”, a w marcu przypomni o PIT-38). Odsetki to zysk, nie liczą się do „odłożonych”.',h:['💰 Majątek → Oszczędności → przy koncie „💰 Oprocentowanie” (albo ⚙️ → Konta → 💰).','Wpisz stawkę, ewentualnie promocję (do kiedy, do jakiej kwoty) i kiedy bank dopisuje odsetki.','W dniu dopisania „Na dziś” pokaże szacunek – „Wpisz” i popraw kwotę z wyciągu, jeśli się różni.','Przy zmianie stawki wpisz nową i datę „od kiedy” – wcześniejsze miesiące liczą się po starej.'],v:40},
  {i:'🐷',t:'Odłożone',s:'ile naprawdę odkładacie',w:'Odłożone to pieniądze przelane na konta oszczędnościowe i inwestycyjne (także wpłaty PPK) minus to, co z nich wypłaciliście. Zmiana kursów inwestycji się nie liczy – pokazuję ją osobno jako „inwestycje zarobiły / straciły”. Dzięki temu cel miesięczny i podsumowania mówią prawdę także, gdy giełda rośnie albo spada.',h:['Budżet – wiersz „🐷 Odłożone w tym miesiącu” pod kafelkami (stuknij, żeby przejść do Oszczędności).','💰 Majątek → Oszczędności → „Ile odłożyliście” – miesiąc, rok i cel miesięczny.','Analiza – kafelek „Odłożone” (procent przychodów) i „zostaje z przychodów”.'],v:30},
  {i:'🐷',t:'Oszczędności',s:'Razem / każde z Was / Wspólne',w:'Konta oszczędnościowe, poduszka bezpieczeństwa, IKE, IKZE, PPK i inwestycje w jednym miejscu, z podziałem na osoby. Na górze to, co najczęściej: ile odłożyliście i cele; FIRE i wykres „Wpłacone a wartość” na dole.',h:['💰 Majątek → „🐷 Oszczędności”.','W zakładkach Mati / Wercia / Wspólne cele z „+ Przydziel” są zaraz pod przyciskami „Odłóż” i „Aktualizuj wartości”.','„🐷 Odłóż” robi przelew na oszczędności, „📈 Aktualizuj wartości” wpisuje wyceny z aplikacji brokerów.','💧 Kaskada nadwyżek (zakładka osoby i zamknięcie miesiąca): dzień przed wypłatą proponuje przelać to, co zostało na koncie bieżącym ponad zapas (250 zł, ⚙️ do zmiany) i opłaty stałe przed wypłatą. Pensja, która już wpłynęła, nie jest nadwyżką. W inne dni pokazuje, kiedy policzy.'],v:47},
  {i:'🧭',t:'Która koperta do czego',s:'cel, roczne, odkładanie na spłatę, projekt',w:'Cztery sposoby na pieniądze „na coś”. 🎯 Cel – jednorazowe marzenie (wakacje, nowe auto): przydzielacie część oszczędności. 📅 Roczne – to, co wraca co rok (OC, prezenty): prawdziwe pieniądze na wspólnym subkoncie. 💰 Odkładanie na spłatę – gdy chcecie spłacić pożyczkę całą naraz. 🏷️ Projekt – nic nie odkłada, liczy, ile coś kosztuje (auto, koty, remont).',h:['Co rok → 📅 Roczne i terminy.','Jednorazowe marzenie → 🎯 Cel w Oszczędnościach.','Spłata pożyczki naraz → przy pożyczce w 🔻 My winni.','„Ile to kosztowało” → 🏷️ Projekt.'],v:32},
  {i:'💰',t:'Koperty na koncie',s:'co z salda konta jest na którą spłatę i cel, a co wolne',w:'Jedno konto może zbierać na kilka rzeczy naraz – np. „Spłata zobowiązań” na pożyczkę i ubezpieczenie. Stuknij konto, a zobaczysz saldo podzielone na koperty: 🔻 spłaty (zobowiązania z wybranym „kontem na spłatę”), 🎯 cele zbierane na tym koncie i 🪙 Wolne.',h:['👛 Konta → stuknij konto.','„⇄ Przesuń” – z koperty do koperty albo z/do Wolne, bez przelewu: saldo i budżet się nie zmieniają.','„✨ Rozdziel wolne” – aplikacja sama rozkłada wolne pieniądze: najpierw najbliższy termin, każda koperta do kwoty, której jej brakuje.','🪙 Drobne wpadają do Wolne. Spłacona pożyczka – to, co zostało w jej kopercie, wraca do Wolne.','🎯 Cel na konkretnym koncie: przy celu „Edytuj” → „Zbieracie na koncie”. Cele bez konta działają jak dotąd (wspólna pula oszczędności).','Gdy w kopertach jest więcej niż na koncie, 🔔 „Na dziś” podpowie, żeby zdjąć różnicę.'],v:78},
  {i:'🎯',t:'Cele-koperty',s:'wakacje, auto, remont',w:'Przydzielacie część oszczędności do celu i widzicie, ile brakuje i ile odkładać miesięcznie do terminu. Konto „Poduszka…” nie liczy się do puli na cele, a karta poduszki odejmuje pieniądze przydzielone do celów – ta sama złotówka nie jest i poduszką, i wakacjami.',h:['💰 Majątek → Oszczędności → zakładka Mati, Wercia albo Wspólne → „+ Dodaj cel”.'],v:37},
  {i:'🛡️',t:'IKE, IKZE, PPK – limity',s:'ile jeszcze można wpłacić',w:'Pilnuję rocznych limitów wpłat. W grudniu przypomnę o IKZE (ulga w PIT), a automat sam znajduje limity na nowy rok i pyta, czy je wpisać.',h:['Karta „Limity” w Oszczędnościach. „✎ Limity” – poprawka ręczna.']},
  {i:'📈',t:'Instrumenty',s:'ETF, akcje, złoto, krypto, lokaty',w:'Na koncie inwestycyjnym zapisujesz zakupy i sprzedaże. Aplikacja liczy wartość, zysk i kwotę „na rękę” po podatku Belki (na IKE/IKZE/PPK bez podatku).',h:['Konto inwestycyjne → „Instrumenty” → „+ Dodaj instrument”.','„Symbol dla automatu” (np. IWDA.UK) – wtedy cenę pobiera automat.','„⚖️ Zapisz wycenę” przenosi wynik do salda konta.']},
  {i:'🏛️',t:'Obligacje skarbowe',s:'EDO, COI, ROS, ROD – liczą się same',w:'Każdy rok odsetkowy liczę z inflacji GUS sprzed 2 miesięcy plus marża – tak jak Ministerstwo Finansów. Przy nowym zakupie podpowiadam oprocentowanie serii w sprzedaży.',h:['Instrument → rodzaj „Obligacje skarbowe”, wpisz liczbę obligacji.','„📅 Oprocentowanie” pokazuje każdy rok i skąd się wziął; rok, który trwa, możesz poprawić według tabeli odsetkowej.','Miesiąc przed wykupem przypomnę w „Na dziś”.'],v:16},
  {i:'🧺',t:'Fundusze PPK i TFI',s:'wybierz fundusz, wpisz jednostki',w:'Automat codziennie pobiera wartość jednostki funduszu, więc PPK wycenia się samo.',h:['Konto PPK → „+ Dodaj instrument” → „Fundusz TFI / PPK” → wybierz fundusz z listy (pogrupowane według instytucji).','Wpisz liczbę jednostek z aplikacji PPK. Później „✎ Liczba jednostek” – raz na jakiś czas wystarczy.'],v:16},
  {i:'👛',t:'Konta i salda',s:'wszystkie konta, wyrównanie',w:'Salda wszystkich kont, z podziałem na osoby i rodzaje („Czyj majątek”). Gdy saldo w aplikacji różni się od banku, wyrównujecie wszystkie salda naraz – na jednym ekranie (pojedynczych kont nie poprawia się osobno).',h:['💰 Majątek → „👛 Konta” → „🏦 Salda”. Kafelek „Na kontach ›” na Budżecie też tu prowadzi.','Czyje konta pokazać – okrągłe guziki „Wszyscy · Mati · Wercia · Wspólne” w karcie z sumą.','„⚖️ Wyrównaj wszystkie salda naraz” (pod listą kont) – wpisz salda z banku, różnice zapiszę jako przelewy albo wyrównania. Konta oznaczę jako sprawdzone dopiero po „Zapisz”. Ten sam przycisk jest w zamknięciu miesiąca.'],v:66},
  {i:'🔗',t:'Usuwanie konta',s:'co z opłatami i pensjami na tym koncie',w:'Konto bez wpisów można usunąć (z wpisami – przenosi się do archiwum). Gdy jeszcze coś go używa – opłata stała, stały przelew, źródło dochodu, PPK, reguła drobnych, subkonto kopert, odkładanie na spłatę albo instrument – od razu pojawia się okienko: co go używa i na które konto to przenieść. Wpisy w Rejestrze się nie zmieniają.',h:['⚙️ → 🏦 Konta → „Edytuj” → „Usuń konto” (albo ⋯ przy koncie w Oszczędnościach).','Wybierz konto docelowe (PPK i instrumenty – konto inwestycyjne) → „Przenieś i usuń konto”.'],v:50},
  {i:'🔻',t:'My winni i Nam winni',s:'kredyty, pożyczki',w:'Zobowiązania (kredyt, raty, pożyczka od rodziny) i pieniądze pożyczone innym. Stan kont się przez nie nie zmienia – w 👛 Konta widać je osobno („do spłaty”, „pożyczone innym”).',h:['💰 Majątek → Konta → „🔻 My winni” albo „🔺 Nam winni” → „+”.','Ratę wpisujesz jak wydatek z wybranym zobowiązaniem – „pozostało” zmniejsza się samo.']},
  {i:'🧮',t:'Raty i odsetki',s:'podpowiedź raty, koniec spłaty',w:'Z oprocentowania nominalnego (nie RRSO) liczę ratę na ten miesiąc, jej część odsetkową, koniec spłaty i odsetki do końca. To podpowiedź – bank liczy co do dnia, więc kwota może się różnić o grosze.',h:['🔻 My winni → Edytuj → „Oprocentowanie nominalne” i „Raty: równe / malejące”. Rata z umowy (jeśli ją wpiszesz) ma pierwszeństwo przed wyliczoną.','„+ Rata” wpisuje podpowiedź – zmień ją, jeśli bank pobrał inną kwotę.','Bez oprocentowania: to, co zostało ÷ miesiące do „Do kiedy”.','Z każdej raty dług zmniejsza się tylko o część kapitałową. Cała rata zostaje wydatkiem w Budżecie.','W dniu raty przypomnę o niej w 🔔 „Na dziś” (chyba że ta rata jest już w 📌 Stałe).'],v:21},
  {i:'💰',t:'Odkładanie na spłatę pożyczki',s:'zbieram i spłacam całość naraz',w:'Co miesiąc odkładasz na konto, a przy pożyczce widzisz, ile już uzbierałeś. Na jedno konto możesz zbierać na kilka pożyczek – każda ma swój licznik. Spłata całości nie liczy się w Budżecie, tylko odsetki.',h:['🔻 My winni → Edytuj pożyczkę → „💰 Zbieram na spłatę całości na koncie”.','„💰 Odłóż” na karcie pożyczki albo zwykły przelew na to konto – w przelewie wpisz, ile na którą pożyczkę (reszta zostaje wolna).','Stały przelew (📌 Stałe) też możesz przypisać do pożyczki – po odhaczeniu odłoży się sam.','„↑ Weź z odłożonych”, gdy potrzebujesz tych pieniędzy na coś innego.','„✅ Spłać całość” – wpisz kapitał i odsetki z banku. Odłożone pieniądze zużyją się same.'],v:20}]},
 {s:'🤖 Automaty',items:[
  {i:'🔔',t:'Na dziś',s:'wszystkie sprawy w jednym miejscu',w:'Wszystko, co czeka: opłaty do odhaczenia, zamknięcie miesiąca, paski pensji, koperty roczne, przypomnienia, końce gwarancji, wykupy obligacji, kopia danych, przekroczony plan, pozycje do zaplanowania i podpowiedzi stałych opłat. Na Budżecie i w Stałych nie ma już ramek z uwagami. Najpilniejsze na górze: po terminie, dziś, jutro. To, co będzie za kilka dni, czeka zwinięte pod „⏳ Wkrótce”.',h:['Stuknij 🔔 – licznik pokazuje, ile spraw czeka na dziś („Wkrótce” się nie liczy).','Przycisk przy sprawie przenosi tam, gdzie trzeba ją załatwić; „Wiem” / „Nie teraz” chowa ją.','„⏳ Wkrótce” – stuknij, żeby rozwinąć: koniec umowy (ponad 2 tygodnie), promocji, gwarancji, wykup obligacji, przypomnienia i terminy wydatków rocznych (ponad tydzień), PIT przed 20 kwietnia.','„💡 Podpowiedzi” (zwinięte, na samym dole) – ciche rady bez powiadomień: plan (przekroczony, do zaplanowania), „Czy starczy?”, przypomnienia 🧭 Doradcy, nowa wycena nieruchomości. Licznik na dzwonku ich nie liczy.'],v:72},
  {i:'📲',t:'Powiadomienia na telefon',s:'rano 7:30 i wieczorem 20:00',w:'Prawdziwe powiadomienia, także gdy aplikacja jest zamknięta: rano „Na dziś”, wieczorem przypomnienie, gdy nic nie wpisano.',h:['⚙️ → 🤖 Automaty → 🔔 Powiadomienia → „Włącz” – każde z Was na swoim telefonie.'],v:13},
  {i:'📧',t:'Maile',s:'kopia i podsumowanie miesiąca',w:'W pierwszą niedzielę miesiąca kopia zapasowa przychodzi mailem do Matiego, a 1. dnia miesiąca oboje (tylko na adresy, którymi logujecie się w aplikacji) dostajecie szczegółowe podsumowanie poprzedniego miesiąca: krótkie wnioski, porównanie z poprzednim miesiącem, średnią z ostatnich miesięcy i tym samym miesiącem rok temu, plan a rzeczywistość, kategorie, największe wydatki, sklepy, Mati ↔ Wercia, oszczędności, cele i to, co czeka w nowym miesiącu.',h:['Nic nie trzeba robić – automat działa sam. Kopię wczytasz w ⚙️ → 🛡️ Bezpieczeństwo → „Wczytaj kopię”.'],v:50},
  {i:'💱',t:'Kursy, ceny, inflacja',s:'automat w dni robocze',w:'W dni robocze ok. 18:30 automat pobiera kursy walut NBP, stopę NBP, inflację GUS, ceny instrumentów i funduszy oraz ofertę obligacji. Na koniec miesiąca sam zapisuje wycenę kont z instrumentami.',h:['Stan automatu: ⚙️ → 🤖 Automaty → „🤖 Automat (GitHub)”.','Wpis „Wycena instrumentów (automat)” możesz usunąć w Rejestrze jak każdy inny.'],v:50}]},
 {s:'⚙️ Ustawienia',items:[
  {i:'🌸',t:'Kwiatki Werci',s:'ozdoby w różowym kolorze, tylko na telefonie Werci',w:'Gdy na telefonie korzysta Wercia i ma różowy kolor, aplikacja dostaje kwiatki: przy powitaniu, zakładkach, w kafelkach ustawień, okienku wpisu, Analizie i pustych ekranach. Paski celów rosną jak łodyżki i zakwitają na 100%, a zamiast konfetti spadają płatki wiśni. To tylko wygląd – dane i obliczenia bez zmian.',h:['⚙️ → 📱 Ten telefon → 🎨 Wygląd → różowy.'],v:45},
  {i:'⚙️',t:'Ustawienia – kafelki',s:'6 części, każda na osobnym ekranie',w:'🏦 Konta – dodawanie, zmiana, oprocentowanie, archiwum. 🗂️ Kategorie i drobne – pozycje budżetu i 🪙 drobne. 📱 Ten telefon – 🎨 wygląd, 🙈 tryb dyskretny, 🐾 kotki, kto korzysta, urodziny. 🛡️ Bezpieczeństwo – kopia danych, wczytanie kopii, ostatnio usunięte, ostatnie zmiany, wylogowanie. 🤖 Automaty – 🔔 powiadomienia, 📧 maile, automat, Siri. 📖 Pomoc – ten przewodnik, pierwsze kroki, wersja demo.',h:['⚙️ w prawym górnym rogu → stuknij kafelek.','„‹ Ustawienia” albo ⚙️ wraca do kafelków.'],v:44},
  {i:'🔔',t:'Każde ma swoje przypomnienia',s:'swoje i wspólne – bez spraw drugiej osoby',w:'W 🔔 „Na dziś” i w powiadomieniach widzisz tylko swoje sprawy i wspólne. Opłaty drugiej osoby nie przeszkadzają. Czyje to jest: „👥 Dotyczy” albo właściciel konta. Wydatki roczne i przypomnienia bez „Dotyczy” są wspólne. Kopia danych, automat i limity IKE/IKZE – tylko u Matiego.',h:['Ustaw „👥 Dotyczy” w opłacie stałej, wydatku rocznym albo przypomnieniu.','Cudze opłaty nadal są w 📌 Stałe → przełącznik osoby.'],v:43},
  {i:'🙀',t:'Cudze konto',s:'kotki pytają przy wpisie',w:'Gdy wpisujesz wydatek, przychód albo przelew z konta drugiej osoby, kotki pytają, czy na pewno – żeby salda się zgadzały. Po „Tak, wiem” do końca dnia nie pytają o to konto. Konta wspólne i przelewy NA konto drugiej osoby nie wywołują pytania. Osoba telefonu jest przypisana na stałe do loginu (⚙️ → „Kto korzysta”).',h:['„Tak, wiem, co robię” – zapisuje.','„Zmień konto” – wraca do okienka, nic się nie zapisuje.'],v:42},
  {i:'🎨',t:'Wygląd',s:'kolor i wielkość tekstu',w:'Każdy telefon ma swój kolor akcentu (Wercia różowy, Mati miętowy – można zmienić) i wielkość tekstu A / A+ / A++.',h:['⚙️ → 📱 Ten telefon → 🎨 Wygląd – stuknij kółko koloru i wielkość tekstu.'],v:17},
  {i:'🙈',t:'Tryb dyskretny',s:'kwoty jako „•••”',w:'Gdy pokazujecie komuś telefon albo otwieracie aplikację przy ludziach: wszystkie kwoty zamieniają się w „•••”. Procenty, paski i wykresy zostają. Dotyczy tylko tego telefonu.',h:['⚙️ → 📱 Ten telefon → 🎨 Wygląd → „🙈 Ukryte”.','Szybciej: przytrzymaj nazwę miesiąca w nagłówku (ok. pół sekundy) – włącza i wyłącza.','Na górze każdego ekranu jest wtedy pasek „Pokaż kwoty”.'],v:26},
  {i:'🚫',t:'Bez przybliżania',s:'podwójne stuknięcie',w:'Podwójne stuknięcie nie przybliża już ekranu (przyciski działają normalnie, także szybkie „+ +”). Przybliżyć można dwoma palcami.',h:['Nic nie trzeba ustawiać – działa samo.'],v:23},
  {i:'🎂',t:'Urodziny',s:'życzenia od Bailey i Ivo',w:'W dniu Waszych urodzin kotki składają życzenia na Budżecie (z konfetti) i rano w powiadomieniu, a drugiej osobie przypominają o życzeniach.',h:['Datę urodzenia zapisujesz raz – kotki pytają o nią przy starcie aplikacji.','Zmiana: ⚙️ → „Ten telefon” → „Kto korzysta z tego telefonu?” → 🎂 Zmień.'],v:33},
  {i:'📚',t:'Ciekawostka dnia',s:'kotki na Budżecie',w:'Uwagi (opłata po terminie, przekroczony plan, blisko limitu) są w 🔔 „Na dziś”, a kotki na Budżecie witają się, chwalą i opowiadają ciekawostkę dnia o budżecie, oszczędzaniu lub inwestowaniu – 366 różnych, jedna na każdy dzień roku, na obu telefonach ta sama. Po południu kotki pokazują ją same. W święta i urodziny są życzenia.',h:['Budżet → dymek kotków.'],v:46},
  {i:'🐾',t:'Bailey i Ivo',s:'dużo, mało albo wcale',w:'Kotki podpowiadają, świętują i żartują. Możesz zostawić tylko ważne komunikaty albo je wyłączyć.',h:['⚙️ → 📱 Ten telefon → 🐾 Bailey i Ivo → Dużo / Mało / Wyłączone.','„Pokaż pierwsze kroki” – krótka wycieczka po aplikacji.']},
  {i:'💾',t:'Kopia danych',s:'plik z całym budżetem',w:'Plik z wszystkimi danymi – na wszelki wypadek: wpisy, konta, plany, paski, cele, a także ustawienia (kaskada, schowane podpowiedzi, koperty roczne, inflacja, limity, urodziny, zamknięcia miesięcy). Kopia z maila zawiera to samo. Tym samym przyciskiem wczytasz kopię lub listę transakcji.',h:['⚙️ → 🛡️ Bezpieczeństwo → „Pobierz kopię” i zapisz plik w Plikach / na Dysku.','„Wczytaj kopię” przyjmuje plik .json i .json.gz z maila.','🔢 Na dole tej strony „Diagnostyka”: wersja aplikacji (vN), liczba wpisów i „pamięć telefonu: trwała ✓” – telefon obiecał nie czyścić danych aplikacji, więc wpis zrobiony bez internetu nie przepadnie.'],v:38},
  {i:'📊',t:'Czego używamy',s:'licznik ekranów, przycisków i kart',w:'Aplikacja po cichu liczy, co otwieracie: zakładki i podstrony, okienka (nowy wpis, pasek, zamknięcie, Na dziś, szukaj…), dodatki zapisane we wpisie (waluta, zdjęcie, podział, zwrot…) i karty w Analizie i Oszczędnościach widoczne na ekranie co najmniej 2 sekundy. Mati i Wercia osobno. Liczby są tylko w Waszym Firebase (nie w kopii danych). Po 2–3 miesiącach widać, co warto uprościć albo usunąć.',h:['⚙️ → 📖 Pomoc → „📊 Czego używamy” → „Pokaż”.','Na górze najczęściej używane (ostatnie 3 miesiące), niżej „Nieużywane od 3 miesięcy” z datą ostatniego użycia.'],v:48},
  {i:'🧪',t:'Wersja demonstracyjna',s:'pokaż komuś aplikację',w:'Osobna wersja z przykładowymi danymi – bez Waszych danych i bez logowania. Każdy gość ma swoją kopię w swojej przeglądarce.',h:['⚙️ → 📖 Pomoc → „🧪 Pokaż komuś aplikację” → „📤 Wyślij link”.'],v:18}]}];
